/* BoxBox Academy – interfejs okna (osadzony w Qt WebEngine). Układ i style z makiety v3 (28.10.2026).
   Dane przychodzą z Pythona przez QWebChannel (obiekt `bridge`); patrz boxbox/gui/data.py.
   Zasada: ten plik tylko rysuje i wysyła akcje; nic nie liczy. */
(() => {
'use strict';
let bridge = null;
let D = null;                 // pełne dane z Pythona
const ui = { mode: 'coach', view: 'start', settingsTab: 'sound', helpTab: 'glossary', overlayVisible: false, notice: null, wizardStep: 0,
             corner: '', lesson: '', lessonCorner: '', sessionName: 'sesja', record: true, overlay: true, quiet: false, photoPicker: false, photos: [],
             tutorial: false, tutorialStep: 0, sortBy: -1, sortDir: 1, busyDismissed: false, bugDesc: '', hudPhotoPicker: false, hudBackground: '',
             skillsTrack: 'all', skillsFocus: null };
const NAV = [['start','Start','home'],['analysis','Analiza','chart'],['progress','Postęp','trend'],['skills','Umiejętności','radar'],['lessons','Lekcje','book'],['driver','Karta kierowcy','id'],['settings','Ustawienia','settings'],['hud','HUD F1','target']];
const H = {start:['Start','Trener na radiu. Twój kolejny krok do szybszej i pewniejszej jazdy.'],analysis:['Analiza','Zobacz, gdzie zyskujesz czas i co poprawić na kolejnym okrążeniu.'],progress:['Postęp','Twoja droga od pierwszego okrążenia do jazdy bez asyst.'],skills:['Umiejętności','Sześć obszarów, sześć wskazówek. Zobacz, na czym warto skupić się teraz.'],lessons:['Lekcje','Jedna umiejętność na raz. Małe kroki, realny postęp.'],driver:['Karta kierowcy','Twoja licencja, statystyki i zdobyte doświadczenie.'],settings:['Ustawienia','Dostosuj swojego trenera, nakładkę i sposób zapisywania sesji.'],help:['Pomoc','Słownik pojęć, samouczek i zgłoszenie problemu.'],wizard:['Pierwsze uruchomienie','Cztery krótkie kroki i jesteś gotowy na pierwszy trening.'],summary:['Podsumowanie sesji','Każda sesja to konkretna informacja, co zrobiłeś dobrze i co dalej.'],hud:['HUD F1 · nakładka na grę','Niezależne moduły przy krawędziach, bez pełnej ramki i bez zasłaniania toru.']};
// samouczek: 7 kroków, każdy przy elemencie na danym ekranie (pozycja dymka z klasy CSS)
const TUTORIAL = [
  ['start','', 'Start','Tu zaczniesz wszystkie treningi. Zostaw to okno otwarte i uruchom grę.'],
  ['start','at-status', 'Pastylka stanu','Zielona pastylka pokazuje, że gra wysyła telemetrię. Szara: program czeka na grę.'],
  ['start','at-drive', 'Przycisk JEDŹ','JEDŹ uruchamia sesję od razu. Przy starcie automatycznym trener rusza sam, gdy przyjdzie telemetria.'],
  ['start','at-panel', 'Panel na żywo','W trakcie jazdy mechanik pokazuje tu zbliżający się zakręt, bieżący cel i ostatnie komunikaty.'],
  ['driver','at-license', 'Karta kierowcy','Twoja licencja: nick, identyfikator, poziom i statystyki. Kliknij plakietkę na Starcie, żeby tu wrócić.'],
  ['progress','', 'Postęp','Czyste okrążenia, trend czasów i krok asyst. Tu widzisz, co już opanowałeś, a nad czym pracować.'],
  ['settings','', 'Ustawienia','Głos mechanika, nakładka HUD i zapisywanie danych. Nakładka wymaga gry w oknie bez ramki.'],
];

const defs=`<svg width="0" height="0" style="position:absolute;overflow:hidden" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs>
<symbol id="i-home" viewBox="0 0 24 24"><path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/></symbol>
<symbol id="i-chart" viewBox="0 0 24 24"><path d="M3 3v18h18"/><path d="m6 15 4-5 4 3 5-7"/></symbol>
<symbol id="i-trend" viewBox="0 0 24 24"><path d="m3 18 7-7 4 4 7-9"/><path d="M16 6h5v5"/></symbol><symbol id="i-radar" viewBox="0 0 24 24"><path d="M12 2 22 9l-4 12H6L2 9z"/><path d="M12 2v9L2 9m10 2 10-2m-10 2-6 10m6-10 6 10"/></symbol>
<symbol id="i-book" viewBox="0 0 24 24"><path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1z"/><path d="M12 6v14"/></symbol>
<symbol id="i-id" viewBox="0 0 24 24"><rect x="2" y="4" width="20" height="16" rx="3"/><circle cx="8" cy="10" r="2"/><path d="M4.5 16c.5-3 6.5-3 7 0M14 9h5m-5 4h5"/></symbol>
<symbol id="i-settings" viewBox="0 0 24 24"><path d="M10 2h4l.7 2.6 2 .9 2.4-1.1 2.7 3-.9 2.3.8 2.1 2.3.8v3.7l-2.3.8-.8 2.1.9 2.3-2.7 3-2.4-1.1-2 .9L14 24h-4l-.7-2.7-2-.9-2.4 1.1-2.7-3 .9-2.3-.8-2.1L0 13.3V9.6l2.3-.8.8-2.1-.9-2.3 2.7-3 2.4 1.1 2-.9z" transform="translate(1 -1) scale(.92)"/><circle cx="12" cy="12" r="3"/></symbol>
<symbol id="i-help" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 1 1 4 2.9c-1 .5-1 1-1 2.1"/><path d="M12 17h.01"/></symbol>
<symbol id="i-play" viewBox="0 0 24 24"><path d="m8 5 11 7-11 7z"/></symbol>
<symbol id="i-stop" viewBox="0 0 24 24"><rect x="5" y="5" width="14" height="14" rx="2"/></symbol>
<symbol id="i-arrow" viewBox="0 0 24 24"><path d="M4 12h16m-7-7 7 7-7 7"/></symbol>
<symbol id="i-user" viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 22a8 8 0 0 1 16 0"/></symbol>
<symbol id="i-volume" viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/></symbol>
<symbol id="i-headphones" viewBox="0 0 24 24"><path d="M3 14v-3a9 9 0 0 1 18 0v3M3 13h5v8H5a2 2 0 0 1-2-2zm13 0h5v6a2 2 0 0 1-2 2h-3z"/></symbol>
<symbol id="i-flag" viewBox="0 0 24 24"><path d="M5 21V3m0 1c6-3 8 3 15 0v11c-7 3-9-3-15 0"/></symbol>
<symbol id="i-target" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/></symbol>
<symbol id="i-clock" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 5v7l4 3"/></symbol>
<symbol id="i-download" viewBox="0 0 24 24"><path d="M12 3v13m-5-5 5 5 5-5M3 20h18"/></symbol>
<symbol id="i-bolt" viewBox="0 0 24 24"><path d="m13 2-9 12h7l-1 8 10-13h-7z"/></symbol>
<symbol id="i-check" viewBox="0 0 24 24"><path d="m4 12 5 5L20 6"/></symbol>
<symbol id="i-shield" viewBox="0 0 24 24"><path d="m12 2 9 4v6c0 6-5 9-9 10-4-1-9-4-9-10V6z"/><path d="m8 12 3 3 5-6"/></symbol>
<symbol id="i-wrench" viewBox="0 0 24 24"><path d="M14 6a6 6 0 0 1 7-3l-4 4 1 3 3 1 3-3a6 6 0 0 1-7 8L8 23a3 3 0 0 1-4-4z" transform="translate(-2 0) scale(.95)"/></symbol>
<symbol id="i-spark" viewBox="0 0 24 24"><path d="m12 1 2.5 8.5L23 12l-8.5 2.5L12 23l-2.5-8.5L1 12l8.5-2.5z"/></symbol>
<symbol id="i-layers" viewBox="0 0 24 24"><path d="m12 3 10 6-10 6L2 9zm-10 11 10 6 10-6"/></symbol>
</defs></svg>`;
const ico=(key)=>`<svg class="svg-icon" aria-hidden="true"><use href="#i-${key}"></use></svg>`;
const esc=(s)=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const switcher=(name,label,description='')=>`<div class="switch-row"><div><div class="switch-title">${label}</div>${description?`<div class="switch-sub">${description}</div>`:''}</div><button type="button" role="switch" aria-checked="${!!val(name)}" aria-label="${label}" class="switch ${val(name)?'on':''}" data-toggle="${name}"></button></div>`;
const tagline=(t)=>`<span class="tag">${t}</span>`;
const progress=(percent)=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,percent||0))}%"></span></div>`;
const head=(title,sub='',extra='')=>`<div class="panel-header"><div><h2 class="section-title">${title}</h2>${sub?`<p class="section-sub">${sub}</p>`:''}</div>${extra}</div>`;
const metric=(value,label,col='')=>`<div class="metric"><div class="num ${col}">${value}</div><div class="caption">${label}</div></div>`;
const sec=(s)=>{s=Math.max(0,Math.floor(s||0));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return (h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(x).padStart(2,'0')};
const deltaCls=(d)=>d==null?'':(d<0?'green':d>0?'amber':'');
const fmtDelta=(d)=>d==null?'–':(d>0?'+':'−')+Math.abs(d).toFixed(2).replace('.',',')+' s';
function brandIcon(size=46){return `<svg viewBox="0 0 490 360" width="${size}" height="${Math.round(size*0.735)}" aria-hidden="true"><g transform="translate(25 20) scale(0.92)"><g fill="#19E6E6"><rect x="21" y="150" width="10" height="20" rx="5"/><rect x="449" y="150" width="10" height="20" rx="5"/><rect x="44" y="139" width="10" height="42" rx="5"/><rect x="426" y="139" width="10" height="42" rx="5"/><rect x="67" y="127" width="10" height="66" rx="5"/><rect x="403" y="127" width="10" height="66" rx="5"/><rect x="90" y="114" width="10" height="92" rx="5"/><rect x="380" y="114" width="10" height="92" rx="5"/><rect x="113" y="128" width="10" height="64" rx="5"/><rect x="357" y="128" width="10" height="64" rx="5"/></g><rect x="127" y="166" width="54" height="130" rx="16" fill="#FFFFFF"/><rect x="299" y="166" width="54" height="130" rx="16" fill="#FFFFFF"/><path d="M205 211 V141 C205 97 220 80 240 80 C260 80 275 97 275 141 V211" fill="none" stroke="#FFFFFF" stroke-width="22" stroke-linecap="round" stroke-linejoin="round"/><path d="M216 197 L264 197 L254 295 Q240 304 226 295 Z" fill="#FFFFFF"/><rect x="100" y="308" width="280" height="14" rx="7" fill="#E8232A"/></g></svg>`}

// wartości przełączników: część w ustawieniach (Python), część lokalnie w oknie
function val(name){ if(['record','overlay','quiet'].includes(name)) return ui[name]; return D.settings[name]; }

const topStatus=()=>{const s=D.status; let txt, cls='';
  if(s.busy){txt=`Port ${s.port} zajęty`;cls='off'}
  else if(s.connected){txt=`Gra połączona · ${esc(s.track||'tor nieznany')} · ${s.rate} pakietów/s`}
  else {txt=`Czekam na grę · port ${s.port}`;cls='off'}
  return `<span class="status ${cls}" id="status-pill"><i class="dot"></i>${txt}</span>`};

// --- pasek komunikatów pod nagłówkiem: błąd zostaje, informacja i sukces znikają po 6 s ---
function currentNotice(){ if(ui.notice) return ui.notice;
  if(D.status.busy&&!ui.busyDismissed) return {type:'error',text:`Port ${D.status.port} zajęty: zamknij inny program z telemetrią`,action:{label:'Sprawdź telemetrię',code:'check-telemetry'},derived:'busy'};
  if(D.live&&D.live.error) return {type:'error',text:D.live.error,derived:'live'};
  return null; }
function noticeMarkup(){const n=currentNotice(); if(!n) return ''; return `<div class="notice ${n.type}" role="alert"><span class="notice-icon">${n.type==='error'?'⚠':n.type==='success'?'✓':'ⓘ'}</span><span class="notice-content">${esc(n.text)}</span>${n.action?btn(n.action.label,n.action.code,'ghost sm'):''}<button class="notice-close" data-action="notice-close" title="Zamknij">×</button></div>`}
let noticeTimer=null;
function showNotice(type,text,action=null){ui.notice={type,text,action};render();clearTimeout(noticeTimer);if(type!=='error')noticeTimer=setTimeout(()=>{ui.notice=null;render()},6000)}
function toast(msg){ const t=/^(błąd|blad|port |nie udało|brak )/i.test(msg)?'error':/^(zapisano|gotowe|zdjęcie|raport)/i.test(msg)?'success':'info'; showNotice(t,msg); }
function emptyState(title,desc,button,action,iconName='◎'){return `<div class="empty-state"><div class="empty-icon">${iconName}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${button?btn(button,action,'cyan'):''}</div>`}
function tutorialBubble(){const step=ui.tutorialStep,t=TUTORIAL[step]; if(!t) return ''; return `<aside class="tutorial ${t[1]}" role="dialog" aria-label="Samouczek"><div class="caps">SAMOUCZEK ${step+1}/${TUTORIAL.length}</div><strong>${esc(t[2])}</strong><p>${esc(t[3])}</p><div class="tutorial-actions">${btn('Zamknij','tutorial-close','ghost sm')}${btn(step===TUTORIAL.length-1?'Zakończ':'Dalej →','tutorial-next','primary sm')}</div></aside>`}

function side(){return `<aside class="side"><div class="brand"><span class="brand-mark">${brandIcon()}</span><span class="brand-txt"><strong>BoxBox</strong><span>ACADEMY</span></span></div><div class="side-overline">NAWIGACJA</div><nav class="nav" aria-label="Nawigacja główna">${NAV.map(([id,label,icon])=>`<button class="nav-item ${ui.view===id?'active':''}" data-nav="${id}" title="${label}">${ico(icon)}<span class="nav-label">${label}</span></button>`).join('')}</nav><div class="side-spacer"></div><div class="side-bottom"><button class="nav-item ${ui.view==='help'?'active':''}" data-nav="help">${ico('help')}<span class="nav-label">Pomoc i wsparcie</span></button><div class="side-card"><div class="side-card-row"><i class="dot" style="${D.status.connected?'':'background:#5b6676;box-shadow:none'}"></i><strong>${D.live?'Sesja na żywo':'System treningowy'}</strong></div><div class="small-txt mt-10">${esc(D.app.game)} · ${D.live?'trener aktywny':(D.status.connected?'gra połączona':'czekam na grę')}</div></div><div class="side-footer"><span>BETA ${esc(D.app.version)}</span><span>${esc(D.app.build)}</span></div></div></aside>`}
function bgTrack(){let m=D.analysis&&D.analysis.map; const pts=m&&m.points&&m.points.length>20?m.points:null;
 let path; if(pts){ const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),x0=Math.min(...xs),y0=Math.min(...ys),sc=820/Math.max(Math.max(...xs)-x0,Math.max(...ys)-y0,1); const n=p=>[90+(p[0]-x0)*sc,90+(p[1]-y0)*sc]; path=pts.map((p,i)=>{const q=n(p);return `${i?'L':'M'}${q[0].toFixed(1)},${q[1].toFixed(1)}`}).join('')+'Z'; if(m.start){const q=n(m.start); m=Object.assign({},m,{start:q})} } else { path='M180,520C140,380 260,230 420,250S700,420 760,330 900,170 980,330 860,620 640,560 420,760 300,700 220,660 180,520Z'; }
 const start=pts&&m.start?`<circle class="start" cx="${m.start[0]}" cy="${m.start[1]}" r="9"/>`:'';
 return `<svg class="bg-track" viewBox="0 0 1000 1000" aria-hidden="true"><path class="road" d="${path}"/><path class="line" d="${path}"/>${start}</svg>`}
function bgLayer(){return `<div class="bg-3d" aria-hidden="true"><div class="bg-grid"></div><div class="bg-glow a"></div><div class="bg-glow b"></div><div class="bg-glow c"></div>${bgTrack()}</div>`}
function shell(){let [title,description]=H[ui.view]||H.start; return `${defs}${bgLayer()}<div class="app-layout">${side()}<main class="main"><header class="header"><div><div class="eyebrow">BOXBOX ACADEMY <span style="color:#46566a;margin:0 7px">/</span> ${esc(D.app.game).toUpperCase()}</div><h1 class="page-title">${title}</h1><p class="page-sub">${description}</p></div><div class="header-right">${topStatus()}</div></header>${noticeMarkup()}${renderView()}<footer class="footer-note"><span><strong>BoxBox Academy</strong> · trener jazdy · wszystkie dane zostają na tym komputerze</span><span>${esc(D.app.version)}</span></footer></main>${ui.overlayVisible&&D.live?overlayUI():''}${ui.tutorial?tutorialBubble():''}</div>`}

const photoStyle=(f)=>{f=f||{}; const x=f.x??50,y=f.y??50,z=(f.zoom??100)/100; return `object-position:${x}% ${y}%;transform:scale(${z});transform-origin:${x}% ${y}%`};
function license(withTip=false){const d=D.driver; const avatar=d.photo?`<img src="${d.photo}" alt="" style="${photoStyle(d.photoFit)}">`:ico('user');
  return `<div class="license" ${withTip?'data-nav="driver" role="button" tabindex="0" title="Otwórz pełną kartę kierowcy"':''}><div class="license-head"><div class="license-brand">${brandIcon(27)}<div><strong>BOXBOX ACADEMY</strong><small>LICENCJA KIEROWCY</small></div></div><strong class="license-level">L${d.level}</strong></div><div class="license-main"><div class="avatar">${avatar}</div>${withTip?'':`<button type="button" class="license-radar-link" data-nav="skills" title="Otwórz analizę umiejętności"><span class="license-radar-graphic">${skillRadarSVG(skillsScores(D.skills&&D.skills.all),null,true)}</span><small>PROFIL UMIEJĘTNOŚCI ↗</small></button>`}<div><div class="license-name">${esc(d.nick||'KIEROWCA')}</div><div class="id">ID: ${esc(d.id)}</div><div style="margin-top:9px">${tagline(esc(D.app.gameShort)+' · Kierowca')}</div></div></div><div class="license-data"><div><small>Krok asyst</small><strong>${esc(d.stepText)}</strong></div><div><small>Tory</small><strong>${esc(d.tracksText)}</strong></div><div><small>Okrążenia</small><strong>${d.laps}</strong></div><div><small>Seria</small><strong>${esc(d.streakText)}</strong></div></div><div class="license-progress">${progress(d.progressPct)}</div><div class="license-foot"><span>${esc(d.nextText)}</span><span>od ${esc(d.since)}</span></div></div>`}

// Start: przed pierwszą sesją pełny hero z hasłem; po sesji niższa karta akcji i „Ostatnia sesja”
// --- Start: Racing Command Center (makieta HTML 28.10): studio bolidu z 24 klatek, Pit control, licencja ---
const CAR_FRAMES=Array.from({length:24},(_,i)=>`img/car/car_${String(i).padStart(2,'0')}.png`);
let carFrame=12;
setInterval(()=>{ try{ if(!D||D.live||ui.view!=='start'||document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches) return; carFrame=(carFrame+1)%CAR_FRAMES.length; document.querySelectorAll('img[data-sprite="car"]').forEach(img=>{img.src=CAR_FRAMES[carFrame]}); }catch(e){} },130);
function carStudio(compact=false){return `<div class="car-visual ${compact?'small-car':''}" aria-hidden="true"><div class="car-stage-grid"></div><div class="ring ring-a"></div><div class="ring ring-b"></div><div class="car-floor"></div><img data-sprite="car" class="car-sprite" src="${CAR_FRAMES[carFrame]}" alt="" draggable="false"><div class="car-reflection"></div></div>`}
function ready(){const last=D.last, todo=D.todo, first=!last, s=D.settings, connected=D.status.connected;
  return `<div class="racing-dashboard"><div class="garage-main"><section class="garage-stage" aria-label="Studio bolidu"><div class="stage-geometry"></div><div class="stage-top"><span class="system-tag"><span class="tiny-led"></span> GARAGE / ${esc(D.app.gameShort).toUpperCase()}</span><span class="system-tag cyan-tag">${connected?'GRA POŁĄCZONA':'CZEKAM NA GRĘ · PORT '+s.port}</span></div><div class="stage-title"><span class="eyebrow">RACING COMMAND CENTER <b> / 01</b></span><h2>${first?'KAŻDY ZAKRĘT':'GOTOWY NA'}<br><em>${first?'MOŻE BYĆ LEPSZY.':'KOLEJNY STINT'}</em></h2><p>${s.autoStart?'Zostaw to okno, uruchom grę i wyjedź na tor: trener wystartuje sam, gdy gra wyśle telemetrię.':first?'Pierwsza sesja to pierwszy krok. Trener ocenia każdy zakręt i mówi, co poprawić.':'Wszystko gotowe. Wybierz tryb i rozpocznij następną sesję.'}</p></div>${carStudio()}<div class="studio-bottom"><span>01 / DRIVING ACADEMY</span><div class="stage-stats"><span><b>${esc(s.voice)}</b> MECHANIK</span><span><b>${s.port}</b> UDP</span><span><b>${esc(D.app.gameShort)}</b></span></div></div></section><div class="garage-lower"><section class="pit-stat"><div class="micro-heading">${first?'PIERWSZY TRENING':'OSTATNIA SESJA'}</div><strong class="pit-stat-value">${last?esc(last.best||'–:–.–––'):'–:–.–––'}</strong><div class="pit-stat-sub">${last?`${esc(last.track)} · ${esc(last.date)} · ${last.laps} okr.${last.delta!=null?' · '+fmtDelta(last.delta):''}`:'Wynik pojawi się po pierwszej sesji'}</div>${last&&last.toWork?`<p class="small-txt">${ico('target')} ${esc(last.toWork)}</p>`:''}${last?`<button data-nav="analysis" class="link-btn">PRZEJRZYJ ANALIZĘ →</button>`:`<button data-action="${s.wizardDone?'tutorial-start':'open-wizard'}" class="link-btn">${s.wizardDone?'OTWÓRZ SAMOUCZEK →':'URUCHOM KREATOR →'}</button>`}</section><section class="pit-stat"><div class="micro-heading">CEL TRENINGU</div><strong class="pit-stat-value cyan-text">${String(todo.streak).padStart(2,'0')} / ${String(todo.needed).padStart(2,'0')}</strong><div class="pit-stat-sub">Czyste okrążenia z rzędu · krok ${todo.step}/4${todo.track?' · '+esc(todo.track):''}</div><div class="mini-progress"><i style="width:${Math.round(100*todo.streak/todo.needed)}%"></i></div><p class="small-txt">Następnie: <b>${esc(todo.nextStep)}</b></p><button data-action="open-lesson" class="link-btn">PRZEJDŹ DO LEKCJI →</button></section></div></div><aside class="garage-controls"><section class="console-panel"><div class="console-top"><span><i class="live-led"></i> PIT CONTROL</span><span>${connected?'GRA · '+esc(D.status.track||''):'READY / 01'}</span></div><div class="console-head"><span class="micro-heading">KONFIGURACJA SESJI</span><h3>${first?'PIERWSZY TRENING':'NOWY TRENING'}<span class="console-chevron">↗</span></h3><p>Trener głosowy · dane lokalne · ${esc(D.app.gameShort)}</p></div><div class="console-fields"><label class="label">TRYB JAZDY</label><div class="segmented race-mode"><button class="segment ${ui.mode!=='race'?'active':''}" data-mode="coach">NAUKA</button><button class="segment ${ui.mode==='race'?'active':''}" data-mode="race" title="Inżynier na radiu: flagi, pit, opony, odstępy">WYŚCIG</button></div><label class="label" for="session-name">NAZWA SESJI</label><input id="session-name" class="field" value="${esc(ui.sessionName)}" placeholder="Np. Monza — hamowanie" maxlength="72"><div class="console-options">${quickSwitch('record','Nagrywaj sesję')}${quickSwitch('overlay','Nakładka HUD')}${quickSwitch('quiet','Tryb cicho')}</div></div><button class="start-race-button" data-action="start-session" id="drive-btn"><span class="race-arrow">▶</span><span>JEDŹ <small>${s.autoStart?'ALBO START AUTOMATYCZNY':'ROZPOCZNIJ SESJĘ'}</small></span><span class="start-angles">≫</span></button><p class="console-caption">MECHANIK · ${esc(s.voice).toUpperCase()} <span>● ${connected?'GRA POŁĄCZONA':'SYSTEM GOTOWY'}</span></p></section><section class="driver-console"><div class="micro-heading">TWOJA LICENCJA · ${esc(D.driver.nick||'KIEROWCA').toUpperCase()}</div>${license(true)}</section></aside></div>`}

function quickSwitch(name,label){return `<div class="switch-row"><button aria-label="${label}" role="switch" aria-checked="${ui[name]}" class="switch ${ui[name]?'on':''}" data-toggle="${name}"></button><span class="switch-title">${label}</span></div>`}

// --- wykresy: tablice 0..1 (własny i referencja) -> ścieżki SVG ---
function graph(key,own,ref,width=570,height=166,extra=null,step=false){ const n=(own&&own.length)||0;
  if(!n){return `<div class="analysis-nolap">${emptyState('Brak danych okrążenia','Wykres pojawi się po pierwszym pełnym okrążeniu.',null,null,'⌁')}</div>`}
  const Y=v=>(14+(1-v)*(height-28)).toFixed(1), X=i=>(i/(n-1)*width).toFixed(1);
  const path=(arr)=>{let d=''; for(let i=0;i<n;i++){ if(step&&i){d+=` L${X(i)} ${Y(arr[i-1])}`} d+=`${i?' L':'M'}${X(i)} ${Y(arr[i])}`} return d};
  const line=path(own), reference=(ref&&ref.length===n)?path(ref):'', grid=[.2,.5,.8].map(y=>`<path d="M0 ${height*y}H${width}" class="chart-grid"/>`).join('');
  const extraPath=(extra&&extra.length===n)?`<path d="${path(extra)}" fill="none" stroke="#ff3c42" stroke-width="1.8" opacity=".9"/>`:'';
  return `<svg class="chart-frame" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img"><defs><linearGradient id="g-${key}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#19e6e6" stop-opacity=".16"/><stop offset="1" stop-color="#19e6e6" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${line} L${width} ${height} L0 ${height}Z" fill="url(#g-${key})"/>${reference?`<path d="${reference}" class="chart-ref"/>`:''}${extraPath}<path d="${line}" class="chart-line"/></svg>`}
// delta czasu w sekundach: jedna linia wokół osi zero, czerwona = strata, zielona = zysk
function graphDelta(values,width=570,height=120,label=''){ if(!values||values.length<2) return `<div class="analysis-nolap">${emptyState('Brak referencji','Delta pojawi się, gdy będzie drugie okrążenie do porównania.',null,null,'⌁')}</div>`;
  const zero=height/2, span=Math.max(0.3,...values.map(v=>Math.abs(v))), scale=(height-28)/2/span;
  const pts=values.map((v,i)=>[width*i/(values.length-1),zero-v*scale]); const segs=[];
  for(let i=1;i<pts.length;i++){const [x1,y1]=pts[i-1],[x2,y2]=pts[i],v1=values[i-1],v2=values[i];
    if(v1*v2<0){const u=v1/(v1-v2),xm=x1+(x2-x1)*u;segs.push(`<path d="M${x1.toFixed(1)} ${y1.toFixed(1)}L${xm.toFixed(1)} ${zero}" stroke="${v1>0?'#ff3c42':'#35d07f'}" stroke-width="3" fill="none"/><path d="M${xm.toFixed(1)} ${zero}L${x2.toFixed(1)} ${y2.toFixed(1)}" stroke="${v2>0?'#ff3c42':'#35d07f'}" stroke-width="3" fill="none"/>`)}
    else segs.push(`<path d="M${x1.toFixed(1)} ${y1.toFixed(1)}L${x2.toFixed(1)} ${y2.toFixed(1)}" stroke="${v2>0?'#ff3c42':'#35d07f'}" stroke-width="3" fill="none"/>`)}
  const [lx,ly]=pts[pts.length-1], last=values[values.length-1], col=last>0?'#ff3c42':'#35d07f', bg=last>0?'#3a1a1e':'#142d24';
  return `<svg class="chart-frame" viewBox="0 0 ${width} ${height}" role="img" aria-label="Delta czasu względem referencji"><path d="M0 ${zero}H${width}" stroke="#9ba6b6" stroke-width="1.5" stroke-dasharray="5 5"/><text x="5" y="${zero-6}" fill="#a9b7c5" font-size="12">0 s</text>${segs.join('')}<circle cx="${lx.toFixed(1)}" cy="${ly.toFixed(1)}" r="4" fill="${col}"/>${label?`<rect x="${width-92}" y="${Math.max(2,Math.min(height-24,ly-17)).toFixed(1)}" width="88" height="22" rx="5" fill="${bg}"/><text x="${width-48}" y="${Math.max(17,Math.min(height-9,ly-2)).toFixed(1)}" text-anchor="middle" fill="${col}" font-size="13" font-weight="800">${esc(label)}</text>`:''}</svg>`}

function live(){const L=D.live; const msgs=L.messages.slice(-3).reverse();
  return `<div class="live-banner"><div class="live-caption"><span class="live-pulse"></span><div><strong style="font-size:12px;letter-spacing:.08em">SESJA NA ŻYWO</strong><div style="font-size:12px;color:#a4aec0;margin-top:4px">${esc(L.name)} · ${sec(L.elapsed)} · ${L.recording?'Nagrywam':'Bez nagrywania'}${L.lesson?' · lekcja: '+esc(L.lesson):''}</div></div></div><div class="toolbar-group">${btn(ui.overlayVisible?'Ukryj podgląd nakładki':'Podgląd nakładki','toggle-overlay','ghost sm')}${btn(`${ico('stop')} Zakończ sesję`,'stop-session','ghost')}</div></div><div class="live-car-ribbon"><div class="live-car-ribbon-copy"><b>MECHANIK NA RADIU / SESJA TRWA</b><span>Animacja bolidu zatrzymana na czas sesji: okno nie zabiera klatek grze.</span></div>${carStudio(true)}</div><div class="board"><div class="stack"><section class="panel" id="live-panel" style="min-height:480px"><div class="spaced"><span class="caps">${esc(L.lapLine||'CZEKAM NA TELEMETRIĘ')} ${L.lapLine?`<span style="margin:0 8px;color:#4c586a">/</span> ${L.pit?'PIT LANE':(ui.mode==='race'?'TRYB WYŚCIGOWY':'TEMPO TRENINGOWE')}`:''}</span>${L.lapLine?tagline(L.invalid?'NIEWAŻNE':'WAŻNE'):''}</div><div class="mt-20"><span class="caps">NASTĘPNY ZAKRĘT</span><div class="live-huge">${esc(L.corner||'—')}</div><div class="inline-icon" style="color:var(--cyan);font-size:14px;font-weight:700">${L.corner?(L.dist==='TERAZ'?'teraz':'za '+esc(L.dist)):''} ${L.dist==='TERAZ'?'<span class="tag cyan">W ZAKRĘCIE</span>':L.corner?'<span class="tag cyan">ZBLIŻASZ SIĘ</span>':''}</div></div>${L.focus?`<div class="callout-amber mt-20"><strong style="font-size:12px;color:var(--amber);letter-spacing:.12em">NA TYM OKRĄŻENIU POPRAW</strong><div style="font-size:14px;font-weight:700;margin-top:7px">${esc(L.focus)}</div></div>`:''}${L.sectors&&L.lapLine?`<div class="mt-20"><span class="caps">SEKTORY · do najlepszych z tej sesji</span><div class="pill-tabs mt-10">${L.sectors.map(sv=>`<span class="tag ${sv.best?'green':sv.delta?'amber':''}">${esc(sv.name)} <span class="mono">${esc(sv.time)}</span>${sv.delta?` <span class="mono">${esc(sv.delta)}</span>`:''}</span>`).join('')}</div></div>`:''}<div class="divider"></div><div class="caps">OSTATNIE KOMUNIKATY MECHANIKA</div><div class="radio-log">${msgs.length?msgs.map(m=>`<div class="radio-entry"><span class="radio-time">${sec(m.t)}</span><p>${esc(m.text)}</p></div>`).join(''):'<div class="radio-entry"><span class="radio-time">--:--</span><p class="small-txt">Mechanik odezwie się po wyjeździe na tor.</p></div>'}</div>${L.goalText?`<div class="callout mt-16"><div class="spaced"><span class="small-txt" style="color:#dce6f1">${esc(L.goalText)}</span><strong class="green">${L.streak} / ${L.needed}</strong></div><div class="mt-10">${progress(100*L.streak/L.needed)}</div></div>`:''}</section></div><div class="stack"><section class="panel">${head('Prędkość','Ostatnie okrążenie vs najlepsze')}${graph('speed',L.chart.own,L.chart.ref)}${L.chart.own.length?`<div class="chart-labels"><span>0 m</span><span>${esc(L.chart.mid)}</span><span>${esc(L.chart.end)}</span></div>`:''}<div class="legend mt-16"><span><i></i> Ostatnie</span><span><i class="ref"></i> Najlepsze</span></div></section><div class="tiles">${metric(esc(L.best||'–'),'Najlepsze dziś')}${metric(fmtDelta(L.delta),'Do referencji',deltaCls(L.delta))}${metric(L.laps,'Okrążenia')}</div><section class="panel">${head('Stan sesji','Rejestrator i stan łącza')}<div class="info-row"><span>Próbkowanie</span><strong class="cyan-text">${L.rate} Hz</strong></div><div class="info-row"><span>Obciążenie</span><strong>${L.cpu}</strong></div><div class="info-row"><span>Plik nagrania</span><strong style="font:12px Consolas,monospace">${esc(L.recordingName||'bez nagrywania')}</strong></div><div class="small-txt mt-16">Sesja zakończy się sama, gdy gra przestanie wysyłać dane${D.settings.autoStopS?` (${D.settings.autoStopS} s)`:''}, albo przyciskiem powyżej.</div></section></div></div>`}

function summary(){const S=D.summary; if(!S) return ready();
  return `<div class="toolbar"><span class="tag green">${ico('check')} SESJA ZAKOŃCZONA</span><div class="toolbar-group">${btn('Nowa sesja','new-session','primary')}${btn('Zobacz analizę →','go-analysis','cyan')}</div></div><section class="panel mb-18"><div class="spaced"><div><div class="caps">${esc(S.track||'').toUpperCase()} · ${esc(S.name).toUpperCase()}</div><h2 style="font-size:28px;letter-spacing:-.05em;margin:8px 0">${S.laps} okrążeń <span style="color:#67798b">/</span> ${sec(S.elapsed)}</h2><p class="page-sub">${S.race?'Inżynier prowadził wyścig; trener techniki milczał.':S.coach?'Trener ocenił każde pełne okrążenie względem referencji.':'Trener nie wystartował (brak pliku toru albo telemetrii); zapisano tylko przebieg.'}</p></div>${tagline(esc(S.date))}</div><div class="mini-metrics mt-20">${metric(esc(S.best||'–'),'Najlepsze okrążenie')}${metric(`${S.clean} / ${S.laps}`,'Czyste okrążenia')}${metric(fmtDelta(S.delta),'Zmiana vs poprzednie sesje',deltaCls(S.delta))}</div>${S.sectorsLine?`<p class="small-txt mt-16">${esc(S.sectorsLine)}</p>`:''}${S.cpu?`<p class="small-txt mt-16">Obciążenie: ${esc(S.cpu)}</p>`:''}</section><div class="grid-2 mb-18"><section class="panel"><div class="inline-icon green" style="font-size:12px;font-weight:800">${ico('check')} DOBRZE</div><h2 class="section-title mt-16">${esc(S.good||'Sesja zapisana')}</h2></section><section class="panel"><div class="inline-icon amber" style="font-size:12px;font-weight:800">${ico('target')} DO PRACY</div><h2 class="section-title mt-16">${esc(S.toWork||'Nic pilnego')}</h2></section></div>${S.race?`<section class="panel mb-18">${head('Wyścig','Pozycje, start, kontakty i kary',`<span class="tag ${S.race.rating>=80?'green':S.race.rating>=50?'amber':'red'}">CZYSTOŚĆ ${S.race.rating}/100</span>`)}${S.race.lines.map(l=>`<div class="info-row"><span>${esc(l)}</span></div>`).join('')}</section>`:''}${S.lesson?`<section class="panel mb-18"><div class="spaced"><div><div class="caps">LEKCJA</div><h2 class="section-title mt-10">${esc(S.lesson.title)}</h2></div><span class="tag ${S.lesson.passed?'green':'amber'}">${S.lesson.passed?'ZALICZONA':'JESZCZE NIE'} · seria ${S.lesson.best}/${S.lesson.needed}</span></div></section>`:''}<section class="panel mb-18">${head('Okrążenia','Każde pełne okrążenie z tej sesji · kliknij Analiza, aby zobaczyć szczegóły · najlepszy sektor na fioletowo',S.idealLap?tagline(`Z najlepszych sektorów: <strong class="mono">${esc(S.idealLap)}</strong>`):'')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Numer</th><th>Czas</th><th>S1</th><th>S2</th><th>S3</th><th>Δ do najlepszego</th><th>Ważne</th><th>Uwagi</th><th></th></tr></thead><tbody>${S.lapRows.map(r=>`<tr><td class="mono">${String(r.number).padStart(2,'0')}</td><td class="mono">${esc(r.time)}</td>${(r.sectors||['-','-','-']).map((sv,i)=>`<td class="mono ${r.bestSectors&&r.bestSectors[i]?'best-sector':''}">${esc(sv)}</td>`).join('')}<td class="mono">${esc(r.delta)}</td><td>${r.valid?'<span class="tag green">Tak</span>':'<span class="tag red">Nie</span>'}</td><td>${r.notes}</td><td><button class="link-btn" data-nav="analysis">Analiza →</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel">${head('Zakręty najlepszego okrążenia','Pomiary z tej sesji względem referencji')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Zakręt</th><th>v_min</th><th>Bieg</th><th>Hamowanie</th><th>Pełny gaz</th><th>Δ czasu</th></tr></thead><tbody>${S.cornerRows.map(r=>`<tr>${r.map(c=>`<td class="mono">${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="callout mt-20"><div class="spaced"><strong style="font-size:12px">Krok ${D.todo.step} · ${esc(D.todo.stepName)}</strong><span class="green" style="font-size:12px;font-weight:800">${D.todo.streak}/${D.todo.needed}</span></div><div class="mt-10">${progress(100*D.todo.streak/D.todo.needed)}</div><p class="small-txt">${esc(D.driver.nextText)}.</p></div><div class="toolbar-group mt-20">${btn('Zobacz analizę','go-analysis','cyan')}${btn('Zapisz raport PDF','session-report','ghost')}${btn('Drukuj','print-pdf','ghost')}${btn('Nowa sesja','new-session','ghost')}</div></section>`}

const MAP_NOTE={recorder:'Obrys z Twojego nagrania (realny ślad auta z gry).',atlas:'Obrys z atlasu torów dopasowany do gry; dokładność ok. 5 m. Nagranie recorderem zastąpi go realnym śladem.',outline:'Obrys z atlasu torów. Meta, zakręty i punkty hamowania pojawią się po przejechaniu kilku zakrętów z trenerem.'};
function mapTrack(){const M=D.analysis.map; if(!M||!M.points.length){return emptyState('Brak kształtu toru','Przejedź jedno okrążenie z trenerem albo nagraj je recorderem, a mapa pojawi się tutaj.',null,null,'⌁')}
  const d=M.points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')+'Z';
  return `<div class="track-map"><svg viewBox="0 0 500 270" role="img" aria-label="Kształt toru"><path class="track-baseline" d="${d}"/><path class="track-main" d="${d}"/><path class="track-dash" d="${d}"/>${(M.drsZones||[]).map(z=>`<path class="track-drs ${z.used?'used':'missed'}" d="${z.points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')}"/>`).join('')}${(M.refBrakes||[]).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#8d98a8" stroke="#0d1623" stroke-width="1.5"/>`).join('')}${(M.brakes||[]).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#ff3c42" stroke="#0d1623" stroke-width="1.5"/>`).join('')}${M.corners.map(c=>`<g class="track-pin ${ui.corner===c.name?'active':''}" data-corner="${esc(c.name)}" role="button" tabindex="0"><circle cx="${c.x}" cy="${c.y}" r="9"/><text x="${c.x+13}" y="${c.y-13}">${esc(c.name)}</text></g>`).join('')}${M.start?`<circle cx="${M.start[0]}" cy="${M.start[1]}" r="5" fill="#35d07f" stroke="#0e1829" stroke-width="3"/>`:''}</svg></div><div class="track-demo-label">${esc(MAP_NOTE[M.source]||'')}</div>`}

function analysis(){const A=D.analysis; const sel=(id,opts,cur)=>`<select class="select" id="${id}">${opts.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(cur)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;
  if(!A.sessions.length) return `<section class="panel">${emptyState('Brak sesji do analizy','Po pierwszym zarejestrowanym okrążeniu zobaczysz wykresy prędkości, gazu i hamulca.','Wróć do Startu','go-start','◌')}</section>`;
  const note=A.notes.find(n=>n.corner===ui.corner); const hasBrakes=A.map&&((A.map.brakes||[]).length||(A.map.refBrakes||[]).length); const hasDrs=A.map&&(A.map.drsZones||[]).length;
  const focusDef=ui.skillsFocus?SKILL_DEFS.find(x=>x.id===ui.skillsFocus):null;
  return `${focusDef?`<div class="skill-analysis-return"><div><strong>Analiza wskazówki · ${focusDef.name}</strong><span>${ui.corner?`Wybrany zakręt: ${esc(ui.corner)}. `:''}Poniżej punkt na mapie i uwagi mechanika.</span></div>${btn('← Umiejętności','skills-back','ghost sm')}</div>`:''}<div class="toolbar"><div class="toolbar-group">${sel('an-session',A.sessions,A.session)}${sel('an-lap',A.laps,A.lap)}${sel('an-comp',A.comps,A.comp)}</div><span class="tag cyan">${ico('chart')} ${esc(A.lengthText)}</span></div><div class="board"><div class="stack"><section class="panel">${head('Kanały telemetrii',`Dystans 0–${esc(A.lengthText)} · kierowca: cyjan, referencja (${esc(A.compLabel)}): szarość`)}<div class="chart-stack"><div><div class="spaced"><span class="caps">PRĘDKOŚĆ</span><span class="small-txt">km/h</span></div>${graph('speed',A.speed.own,A.speed.ref,570,126)}</div><div><div class="spaced"><span class="caps">GAZ (cyjan) I HAMULEC (czerwony)</span><span class="small-txt">%</span></div>${graph('pedal',A.pedal.own,A.pedal.ref,570,126,A.pedal.brake)}</div></div><div class="chart-labels">${A.axis.map(x=>`<span>${esc(x)}</span>`).join('')}</div></section><section class="panel">${head('Rozszerzone kanały','Bieg, kierownica, DRS, bateria ERS i delta czasu względem referencji')}<div class="chart-stack"><div class="mt-16"><div class="spaced"><div class="caps">BIEG</div><span class="small-txt">1–8</span></div>${graph('gear',A.gear.own,A.gear.ref,570,72,null,true)}</div><div class="mt-16"><div class="spaced"><div class="caps">KIEROWNICA</div><span class="small-txt">lewo · prawo</span></div>${graph('steer',A.steer.own,A.steer.ref,570,72)}</div>${A.drs.own.length?`<div class="mt-16"><div class="spaced"><div class="caps">DRS</div><span class="small-txt">${A.drs.zones?`${A.drs.used} z ${A.drs.zones} stref włączone`:'skrzydło otwarte = wysoko'}</span></div>${graph('drs',A.drs.own,null,570,52,null,true)}</div>`:''}${A.ers.own.length?`<div class="mt-16"><div class="spaced"><div class="caps">BATERIA ERS</div><span class="small-txt">0–4 MJ · referencja: szarość</span></div>${graph('ers',A.ers.own,A.ers.ref,570,72)}</div>`:''}<div class="mt-16"><div class="spaced"><div class="caps">DELTA CZASU</div><span class="small-txt">0 = referencja · powyżej wolniej · poniżej szybciej</span></div>${graphDelta(A.delta.values,570,120,A.delta.end)}</div></div><div class="chart-labels">${A.axis.map(x=>`<span>${esc(x)}</span>`).join('')}</div></section></div><div class="stack"><section class="panel">${head('Mapa toru — '+esc(A.track),'Kliknij zakręt, aby obejrzeć uwagi mechanika',`<span class="tag">${A.map&&A.map.corners?A.map.corners.length:0} zakrętów</span>`)}${mapTrack()}${hasBrakes||hasDrs?`<div class="legend mt-16">${hasBrakes?`<span><i class="red"></i> Punkt hamowania kierowcy</span><span><i class="ref"></i> Referencja</span>`:''}${hasDrs?`<span><i class="green"></i> Strefa DRS włączona</span><span><i class="amber"></i> Strefa DRS pominięta</span>`:''}</div>`:''}<div class="callout mt-16"><div class="spaced"><span class="caps">WYBRANY ZAKRĘT</span><strong class="cyan-text">${esc(ui.corner||'—')}</strong></div><p class="small-txt" style="margin-bottom:0">${note?esc(note.text):'Kliknij zakręt na mapie albo uwagę poniżej.'}</p></div></section><section class="panel">${head('Uwagi mechanika','Kliknij komunikat, aby wyróżnić zakręt')}${A.notes.length?A.notes.map(r=>`<button class="note-item ${ui.corner===r.corner?'active':''}" data-corner="${esc(r.corner)}"><span class="note-num">${esc(r.corner)}</span><div style="flex:1;font-size:13px;line-height:1.55">${esc(r.text)}<small>${esc(r.delta)}</small></div></button>`).join(''):'<p class="small-txt">Brak uwag: czyste okrążenie.</p>'}<div class="toolbar-group mt-16">${btn('Eksport CSV','export-csv','ghost sm')}${btn('Drukuj PDF','print-pdf','ghost sm')}</div></section></div></div>`}

const lapSeconds=(t)=>{const m=/(\d+):(\d+)[.,](\d+)/.exec(t||''); return m?(+m[1])*60+(+m[2])+(+m[3])/1000:Number.MAX_SAFE_INTEGER};
function consistencyRow(P){const c=P.consistency, cl=P.clean, tn=P.thenNow; if(!c) return '';
  const cons=`<section class="panel">${head('Spójność jazdy',`Rozrzut czasów z ostatnich ${c.laps} ważnych okrążeń`,tagline(esc(c.label)))}<div class="spaced"><div><div class="caps">ROZRZUT</div><strong class="big-number mono" style="font-size:34px">${esc(c.spread)}</strong></div><div style="text-align:right"><div class="caps">CZYSTE OKRĄŻENIA</div><strong class="big-number" style="font-size:34px">${esc(cl.share)}</strong><div class="small-txt">${cl.cleanLaps} z ${cl.laps} przejazdów</div></div></div><p class="small-txt mt-16">${esc(c.advice)}</p></section>`;
  const then=tn?`<section class="panel">${head('Wtedy vs dziś',`${esc(tn.thenLabel)} i ${esc(tn.nowLabel)} na tym torze`,tn.bestDelta!=null?tagline(fmtDelta(tn.bestDelta)):'')}<div class="table-wrap"><table class="data-table"><thead><tr><th></th><th>${esc(tn.thenLabel)}</th><th>${esc(tn.nowLabel)}</th></tr></thead><tbody>${tn.rows.map(r=>`<tr><td>${esc(r[0])}</td><td class="mono">${esc(r[1])}</td><td class="mono">${esc(r[2])}</td></tr>`).join('')}</tbody></table></div><p class="small-txt mt-16">${esc(tn.summary)}</p></section>`:`<section class="panel">${head('Wtedy vs dziś','Porównanie pojawi się po drugim dniu jazdy na tym torze')}<p class="small-txt">Wróć na ten tor innego dnia, a zobaczysz, co się zmieniło: najlepszy czas, średnie okrążenie i odsetek czystych.</p></section>`;
  return `<div class="grid-2 mb-18">${cons}${then}</div>`}
function progressScreen(){const P=D.progress; if(!P.tracks.length) return `<section class="panel">${emptyState('Brak okrążeń','Zapisz pierwszy przejazd, aby odblokować wykresy postępu i listę zakrętów.','Zacznij trening','go-start','◇')}</section>`;
  const cols=['Data','Okrążenie','Czas','S1','S2','S3','Δ','Ważne','TC','ABS','Skrzynia','Uwagi'];
  const rows=P.history.slice(); if(ui.sortBy>=0){const i=ui.sortBy; rows.sort((a,b)=>{let r; if(i===2) r=lapSeconds(a[2])-lapSeconds(b[2]); else if((i>=3&&i<=6)||i===11) r=(parseFloat(String(a[i]).replace(',','.'))||(i===6?0:1e9))-(parseFloat(String(b[i]).replace(',','.'))||(i===6?0:1e9)); else r=String(a[i]).localeCompare(String(b[i]),'pl',{numeric:true}); return ui.sortDir*r})}
  return `<div class="toolbar"><div class="pill-tabs">${P.tracks.map(t=>`<button class="pill ${P.active===t?'active':''}" data-track="${esc(t)}">${esc(t)}</button>`).join('')}</div><span class="tag cyan">${esc(D.app.gameShort)} · KROK ${P.step} / 4</span></div><div class="grid-2 mb-18"><section class="panel"><div class="spaced"><div><div class="caps">AKTUALNY POZIOM</div><h2 style="font-size:27px;letter-spacing:-.04em;margin-top:9px">Krok ${P.step}: <span class="cyan-text">${esc(P.stepName)}</span></h2></div><strong class="cyan-text big-number" style="font-size:42px">L${P.step}</strong></div><div class="spaced mt-20"><span class="small-txt">Czyste okrążenia z rzędu</span><strong>${P.streak} / ${P.needed}</strong></div>${progress(100*P.streak/P.needed)}<p class="small-txt">${P.nextStep?`Następny krok: <strong style="color:#dce6f1">${esc(P.nextStep)}</strong>. ${esc(P.nextText)}`:'Jedziesz bez asyst: teraz pracujemy nad czasem.'}</p></section><section class="panel">${head('Trend czasów',`Ostatnie ${P.trend.length} okrążeń · ${esc(P.active)}`,P.trendDelta!=null?tagline(fmtDelta(P.trendDelta)):'')}${graph('trend',P.trend,null,570,147)}${P.trend.length?`<div class="chart-labels"><span>${P.trend.length} okrążeń temu</span><span>Teraz</span></div>`:''}<div class="step-results"><div class="caps">NAJLEPSZE CZASY WEDŁUG KROKU ASYST</div>${P.bestPerStep.map(x=>`<div><span>${esc(x[0])}</span><strong class="mono">${esc(x[1])}</strong></div>`).join('')}${P.idealLap?`<div><span>Z najlepszych sektorów (${P.bestSectors.map(esc).join(' · ')})</span><strong class="mono cyan-text">${esc(P.idealLap)}</strong></div>`:''}</div></section></div><div class="grid-2 mb-18"><section class="panel">${head('Zakręty opanowane','Ostatnie 3 ważne okrążenia bez uwag')}<div class="pill-tabs">${P.mastered.length?P.mastered.map(c=>`<span class="tag green">${ico('check')} ${esc(c)}</span>`).join(''):'<span class="small-txt">jeszcze żaden</span>'}</div></section><section class="panel">${head('Do pracy','Nad tymi zakrętami pracuj w kolejnej sesji')}<div class="pill-tabs">${P.todo.length?P.todo.map(c=>`<span class="tag amber">${esc(c.corner)} · ${esc(c.rule)}</span>`).join(''):'<span class="small-txt">nic pilnego</span>'}</div></section></div>${consistencyRow(P)}<section class="panel mb-18">${head('Kamienie milowe','Odznaki przyznawane za konsekwentne treningi')}<div class="badges">${P.badges.map(r=>`<div class="achievement ${r.got?'':'locked'}" title="${esc(r.hint)}"><span class="badge-icon">${ico(r.icon)}</span><strong>${esc(r.name)}</strong></div>`).join('')}</div></section><section class="panel">${head('Historia przejazdów','Sortowanie nagłówkiem · najkrótsze poprawne okrążenie wyróżnione')}<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map((n,i)=>`<th><button class="sort-head" data-sort="${i}">${n}${i===ui.sortBy?(ui.sortDir===1?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r[13]?'best-lap':''}">${r.slice(0,12).map((v,i)=>`<td ${i>=2&&i<=6?`class="mono ${i>=3&&i<=5&&v===P.bestSectors[i-3]&&v!=='-'?'best-sector':''}"`:''}>${i===11&&r[12]?`<span class="tip-holder" tabindex="0"><u style="text-decoration-style:dotted;cursor:help">${esc(v)} uwagi</u><span class="tip-text">${esc(r[12])}</span></span>`:esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}

function lessons(){const Ls=D.lessons; const cur=Ls.cards.find(c=>c.id===ui.lesson)||Ls.cards[0]; if(cur&&!ui.lesson) ui.lesson=cur.id;
  const cornerSel=cur&&cur.cornerOnly?(Ls.corners.length?`<div class="mt-16"><label for="lesson-corner" class="label">WYBIERZ ZAKRĘT DO TRENINGU</label><select id="lesson-corner" class="select">${Ls.corners.map(c=>`<option value="${c.number}" ${String(c.number)===String(ui.lessonCorner)?'selected':''}>${esc(c.name)} (zakręt ${c.number})</option>`).join('')}</select></div>`:`<div class="mt-16"><label class="label" for="lesson-corner">ZAKRĘT DO ĆWICZENIA (numer z gry, np. 1)</label><input id="lesson-corner" class="field" style="max-width:160px" value="${esc(ui.lessonCorner||'')}" placeholder="np. 1"></div>`):'';
  return `<div class="toolbar"><span class="caps">TWÓJ PROGRAM TRENINGOWY · FUNDAMENTY</span><span class="tag green">${Ls.cards.filter(c=>!c.premium).length} LEKCJE STARTOWE · DARMOWE</span></div><div class="lesson-grid">${Ls.cards.filter(c=>!c.premium).map(c=>`<section class="panel lesson-card"><div class="spaced"><div class="lesson-icon">${ico(c.icon)}</div><span class="tag ${c.status==='Zaliczona'?'green':c.status.includes('toku')?'cyan':''}">${esc(c.status)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><div class="lesson-card-bottom"><span class="tiny">${ico('clock')} ${c.laps} okrążeń</span><button class="link-btn" data-lesson="${esc(c.id)}">${c.status==='Zaliczona'?'Powtórz':'Szczegóły'} →</button></div></section>`).join('')}</div>${cur?`<div class="panel mt-20"><div class="lesson-detail"><div><div class="caps">WYBRANA LEKCJA</div><h2 style="font-size:26px;letter-spacing:-.045em;margin:10px 0">${esc(cur.title)}</h2><p class="small-txt">${esc(cur.goal)}</p>${cur.explain?`<p class="small-txt">${esc(cur.explain)}</p>`:''}${cornerSel}<div class="callout mt-16"><strong style="font-size:12px">Cel mierzalny</strong><p class="small-txt" style="margin:7px 0 0">${esc(cur.passText)} Trener skupia się wyłącznie na wybranej umiejętności.</p></div><div class="mt-20">${btn(`${ico('play')} Zacznij lekcję`,'start-lesson','primary')}</div></div><div class="exercise-road"><svg viewBox="0 0 350 170" aria-label="Schemat zakrętu"><path d="M16 120H105Q135 120 144 98L164 57Q176 23 216 24H337" fill="none" stroke="#536275" stroke-width="28" stroke-linecap="round"/><path d="M16 120H105Q135 120 144 98L164 57Q176 23 216 24H337" fill="none" stroke="#9faebe" stroke-width="3" stroke-dasharray="7 8"/><circle cx="99" cy="120" r="8" fill="#ff3c42"/><path d="M99 106V59" stroke="#ff3c42" stroke-width="1.5" stroke-dasharray="3 5"/><text x="68" y="47" font-size="10" fill="#ff777b">HAMOWANIE</text><circle cx="197" cy="30" r="6" fill="#19e6e6"/><text x="214" y="63" font-size="10" fill="#19e6e6">APEKS</text></svg></div></div></div>`:''}<section class="panel mt-20"><div class="spaced"><div><h2 class="section-title">Rozbudowany plan nauki</h2><p class="section-sub">${Ls.cards.filter(c=>c.premium).map(c=>esc(c.title)).join(' · ')} i tryb „wytłumacz mi”.</p></div><span class="tag planned">PO BECIE</span></div></section>`}

function photoFitEditor(d){const f=ui.fitDraft||(ui.fitDraft={...d.photoFit});
  return `<div class="photo-fit"><div class="photo-fit-preview" id="photo-fit-preview" title="Przeciągnij, aby przesunąć"><img id="photo-fit-img" src="${d.photo}" alt="" style="${photoStyle(f)}" draggable="false"></div><div class="photo-fit-controls"><label>Powiększenie <span class="mono" id="fit-zoom-out">${f.zoom}%</span><input type="range" id="fit-zoom" min="100" max="300" step="5" value="${f.zoom}"></label><label>Poziomo<input type="range" id="fit-x" min="0" max="100" value="${f.x}"></label><label>Pionowo<input type="range" id="fit-y" min="0" max="100" value="${f.y}"></label><div class="toolbar-group">${btn('Zapisz dopasowanie','photo-fit-save','cyan sm')}${btn('Wyśrodkuj','photo-fit-reset','ghost sm')}</div><p class="small-txt" style="margin:0">Przeciągnij zdjęcie w podglądzie albo użyj suwaków. Tak samo wygląda na plakietce.</p></div></div>`}
function applyFitDraft(){const f=ui.fitDraft; if(!f) return; const img=document.getElementById('photo-fit-img'); if(img) img.style.cssText=photoStyle(f); const z=document.getElementById('fit-zoom'),x=document.getElementById('fit-x'),y=document.getElementById('fit-y'),o=document.getElementById('fit-zoom-out'); if(z) z.value=f.zoom; if(x) x.value=f.x; if(y) y.value=f.y; if(o) o.textContent=f.zoom+'%'}
function driver(){const d=D.driver;
  return `<div class="grid-2"><div class="stack"><section class="panel" id="license-panel"><div class="spaced mb-18"><div><h2 class="section-title">Licencja kierowcy</h2><p class="section-sub">Zdobywasz poziom wraz z kolejnymi krokami asyst.</p></div>${tagline('POZIOM L'+d.level)}</div><div class="full-license">${license()}</div><div class="toolbar-group mt-20">${btn(`${ico('download')} Zapisz plakietkę jako PNG`,'export-license','cyan')}${btn('Jak działa licencja?','license-help','ghost')}</div></section><section class="panel">${head('Informacje kierowcy')}<div class="setting-block"><label class="label" for="driver-nick">NICK</label><div class="form-flex"><input id="driver-nick" class="field" value="${esc(d.nick)}" maxlength="24">${btn('Zapisz','save-nick','cyan sm')}</div></div><div class="info-row"><span>Identyfikator</span><strong>${esc(d.id)}</strong></div><div class="info-row"><span>Dołączył</span><strong>${esc(d.since)}</strong></div><div class="setting-block"><div class="setting-head"><div><strong>Zdjęcie</strong><small>Wybierz z Obrazów lub Pulpitu, albo przeciągnij plik na to okno.</small></div><span class="toolbar-group">${d.photo?btn(ui.photoFit?'Zamknij dopasowanie':'Dopasuj zdjęcie','photo-fit','ghost sm'):''}${btn(ui.photoPicker?'Zamknij':'Wybierz zdjęcie','pick-photo','ghost sm')}</span></div>${ui.photoFit&&d.photo?photoFitEditor(d):''}${ui.photoPicker?`<div class="photo-grid">${ui.photos.length?ui.photos.map(p=>`<button data-photo="${esc(p.path)}" title="${esc(p.name)}"><img src="${p.thumb}" alt=""></button>`).join(''):'<p class="small-txt">Brak obrazów w folderach Obrazy i Pulpit. Przeciągnij plik na okno.</p>'}</div>`:''}</div><div class="setting-block">${switcher('consent','Anonimowe statystyki do przyszłego rankingu','Domyślnie wyłączone. W becie nic nie jest wysyłane.')}</div></section></div><div class="stack"><div class="grid-2">${metric(d.sessions,'Sesje')}${metric(d.laps,'Okrążenia')}${metric(d.tracks.length,'Tory')}${metric(esc(d.hours),'Godzin na torze')}</div><section class="panel">${head('Twoje tory','Najlepsze czasy i aktualne kroki asyst')}${d.tracks.length?d.tracks.map(t=>`<div class="info-row"><span><strong style="color:#e3e9f0">${esc(t.name)}</strong><div class="small-txt">${t.mastered} / ${t.corners} zakrętów · ${t.laps} okr.</div></span><strong>${esc(t.best)}<br><small style="color:${t.step>1?'var(--cyan)':'#96a5b7'}">Krok ${t.step}</small></strong></div>`).join(''):'<p class="small-txt">Jeszcze żadnego toru.</p>'}</section><section class="panel"><div class="inline-icon">${[1,2,3,4].map(l=>`<span class="tag ${l<d.level?'green':l===d.level?'cyan':''}">L${l}</span>${l<4?`<div class="progress" style="flex:1">${progress(l<d.level?100:l===d.level?d.progressPct:0)}</div>`:''}`).join('')}</div><p class="small-txt mt-16">L1 — automat i pełne asysty · L2 — TC średnia · L3 — bez TC · L4 — bez TC i ABS.</p></section></div></div>`}

function settings(){let tabs=[['sound','Dźwięk'],['overlay','Nakładka'],['game','Gra'],['data','Dane'],['help','Pomoc']];return `<div class="settings-grid"><div class="panel" style="align-self:start;padding:13px"><nav class="settings-side">${tabs.map(t=>`<button class="${ui.settingsTab===t[0]?'active':''}" data-settings="${t[0]}">${t[1]}</button>`).join('')}</nav></div><section class="panel" style="min-height:425px">${settingsBody()}</section></div>`}
function settingsBody(){const s=D.settings; switch(ui.settingsTab){
 case 'sound':return `${head('Dźwięk i mechanik','Ustaw sposób, w jaki trener komunikuje się z kierowcą')}<div class="setting-block"><div class="setting-head"><div><strong>Głośność komunikatów</strong><small>Ponad 100% to wzmocnienie na tle głośnej gry.</small></div><strong class="cyan-text">${s.volume}%</strong></div><input type="range" class="slider" id="volume" min="30" max="300" step="10" value="${s.volume}"><div>${btn(`${ico('volume')} Odtwórz próbkę`,'audio-sample','ghost sm')}</div></div><div class="setting-block">${switcher('quietDefault','Tryb cicho domyślnie','Mechanik odzywa się tylko po zakończeniu okrążenia.')}</div><div class="setting-block">${switcher('explain','Tryb „wytłumacz mi”','Przy pierwszej uwadze danego typu trener mówi dłuższą wersję z wyjaśnieniem.')}</div><div class="setting-block"><label class="label">GŁOS MECHANIKA</label><select class="select" disabled><option>${esc(s.voice)} · neutralny i dojrzały</option></select><p class="small-txt">Inne głosy: po becie.</p></div>`;
 case 'overlay':return `<div class="callout mb-18">Nakładka nad F1 25 wymaga trybu <strong>Okno bez ramki (Borderless)</strong>; w wyłącznym pełnym ekranie nie będzie widoczna.</div>${head('Nakładka HUD F1','Elementy przy krawędziach gry · modułowa i przezroczysta')}<div class="setting-block">${switcher('overlayDefault','Pokazuj HUD podczas treningu','Nie zasłania całej gry. Każdy moduł działa niezależnie.')}</div><div class="setting-block"><div class="setting-head"><strong>Skala modułów</strong><strong class="cyan-text">${s.scale}%</strong></div><input type="range" class="slider" min="65" max="160" step="5" id="scale" value="${s.scale}"></div><div class="setting-block"><div class="setting-head"><strong>Krycie tła</strong><strong class="cyan-text">${s.opacity}%</strong></div><input type="range" class="slider" id="opacity" min="0" max="100" step="5" value="${s.opacity}"></div><div class="setting-block">${btn('Otwórz edytor HUD','open-hud','cyan')} ${btn('Pokaż nakładkę na 5 s','preview-overlay','ghost')}<p class="small-txt">W edytorze przesuwasz, wyłączasz i skalujesz poszczególne moduły.</p></div>`;
 case 'game':return `${head('Gra i telemetria',`Połączenie UDP: ${esc(D.app.game)}`)}<div class="setting-block"><label class="label">GRA</label><select class="select" disabled><option>${esc(D.app.gameShort)} · jedyna obsługiwana gra w becie</option></select><p class="small-txt">Wybór gry odblokuje się po dodaniu kolejnych adapterów.</p></div><div class="info-row"><span>Format pakietów</span><strong>${esc(D.status.fmt||'2025 / 2026')}</strong></div><div class="info-row"><span>Port UDP</span><strong><input id="port" class="field" style="width:110px;padding:6px 10px" value="${s.port}"></strong></div><div class="info-row"><span>Adres IP w grze</span><strong>127.0.0.1</strong></div><div class="setting-block">${switcher('autoStart','Start automatyczny','Trener rusza sam, gdy gra zacznie wysyłać telemetrię; sesja kończy się sama bez sygnału.')}</div><div class="mt-20">${btn('Sprawdź telemetrię (nasłuch 5 s)','check-telemetry','cyan')} <span class="small-txt" id="check-result">${esc(D.wizard.checkResult||'')}</span></div>`;
 case 'data':return `${head('Dane i nagrania','Prywatne pliki na Twoim komputerze')}<div class="setting-block"><div class="setting-head"><div><strong>Folder danych</strong><small>${esc(D.app.dataDir)}</small></div>${btn('Otwórz folder','open-data','ghost sm')}</div></div><div class="setting-block"><div class="setting-head"><div><strong>Folder nagrań</strong><small>${esc(D.app.recordingsDir)}</small></div>${btn('Otwórz folder','open-recordings','ghost sm')}</div></div><div class="setting-block">${switcher('record','Domyślnie nagrywaj sesje','Pozwala wrócić do przebiegów i zgłosić błąd z nagraniem.')}</div><div class="setting-block"><div class="info-row"><span>Sesje w bazie</span><strong>${D.driver.sessions}</strong></div><div class="info-row"><span>Okrążenia w bazie</span><strong>${D.driver.laps}</strong></div></div><div class="setting-block">${btn('Zapakuj raport błędu','report-bug-now','cyan')}<p class="small-txt">${esc(D.wizard.bugResult||'Pakuje dziennik, bazę, ustawienia i ostatnie nagranie do ZIP; ścieżka pojawi się tutaj.')}</p></div>`;
 case 'help':return `${head('Pomoc i aktualizacje','Najważniejsze zasoby dla początkującego')}<div class="setting-block">${btn('Uruchom kreator jeszcze raz','open-wizard','cyan')} ${btn('Otwórz samouczek','tutorial-start','ghost')}</div><div class="setting-block">${btn('Słownik pojęć','glossary','ghost')} ${btn('Zgłoś błąd','report-bug','ghost')}</div><div class="info-row"><span>Wersja</span><strong>${esc(D.app.version)} · ${esc(D.app.build)}</strong></div><div class="info-row"><span>Aktualizacje automatyczne</span><span class="tag planned">PO BECIE</span></div>`;}}

function wizard(){const titles=['Telemetria','Głośniki','Asysty','Kierowca'];let s=ui.wizardStep;const W=D.wizard;
  return `<div class="wizard-shell"><div class="steps">${titles.map((title,i)=>`<div class="step ${i===s?'active':i<s?'done':''}"><b>${i<s?'✓':String(i+1).padStart(2,'0')}</b>${title}</div>`).join('')}</div><section class="panel" style="padding:33px;min-height:400px"><div class="caps">KROK ${s+1} / 4</div><h2 style="font-size:29px;letter-spacing:-.05em;margin:12px 0">${['Połącz telemetrię z grą','Sprawdź dźwięk mechanika','Ustaw asysty na początek','Stwórz kartę kierowcy'][s]}</h2><p class="small-txt mb-18">${['Sprawdź, czy gra wysyła dane do BoxBox Academy.','Komunikaty trenera powinny być wyraźne, ale nie za głośne.','To zalecany zestaw dla pierwszych treningów.','Wybierz nazwę wyświetlaną na Twojej licencji.'][s]}</p>${s===0?`<div class="info-grid">${[['Telemetria UDP','Włączona'],['Tryb rozgłaszania','Wyłączony'],['Adres IP','127.0.0.1'],['Port',String(D.settings.port)],['Częstotliwość','60 Hz'],['Format','2025 lub 2026'],['Twoja telemetria','Publiczna']].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="mt-20">${btn(W.checking?'Nasłuchuję...':'Sprawdź (nasłuch 5 s)','check-telemetry','cyan',W.checking?'disabled':'')}<p class="small-txt" id="check-result">${esc(W.checkResult||'W grze: Ustawienia → Telemetria. Potem wróć tu i naciśnij Sprawdź.')}</p></div>`:s===1?`<div class="callout"><div class="inline-icon">${ico('headphones')} <strong>Test głośników</strong></div><p class="small-txt">Kliknij „Odtwórz powitanie”, następnie wybierz wynik testu.</p><div class="toolbar-group mt-16">${btn('Odtwórz powitanie','audio-sample','cyan')}${btn('Słyszę','hear-yes','ghost')}${btn('Nie słyszę','hear-no','ghost')}</div><p class="small-txt mt-10">${esc(W.hearResult||'')}</p></div>`:s===2?`<div class="info-grid">${[['Skrzynia biegów','Automatyczna'],['Kontrola trakcji (TC)','Pełna'],['ABS','Włączony'],['Linia jazdy','Pełna'],['Asysta ERS','Wyłączona'],['Flashback','Nie używaj']].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="callout mt-20"><strong>Trener powie, kiedy co zdjąć.</strong> Po trzech czystych okrążeniach z rzędu zaproponuje kolejny krok.</div>`:`<div class="form-flex"><div><label class="label" for="driver-nick">NICK KIEROWCY</label><input id="driver-nick" class="field" value="${esc(D.driver.nick)}" maxlength="24" placeholder="np. Driver77"></div><div><span class="label">ZDJĘCIE</span><div class="mt-10">${btn(ui.photoPicker?'Zamknij':'Wybierz z Obrazów lub Pulpitu','pick-photo','ghost sm')}</div></div></div>${ui.photoPicker?`<div class="photo-grid">${ui.photos.length?ui.photos.map(p=>`<button data-photo="${esc(p.path)}" title="${esc(p.name)}"><img src="${p.thumb}" alt=""></button>`).join(''):'<p class="small-txt">Brak obrazów w folderach Obrazy i Pulpit. Dodasz zdjęcie później w Karcie kierowcy.</p>'}</div>`:''}<div class="setting-block mt-16">${switcher('consent','Anonimowe statystyki do przyszłego rankingu','Opcjonalne, domyślnie wyłączone. W becie nic nie jest wysyłane.')}</div>`}<div class="spaced mt-20"><div>${btn('Wstecz','wizard-back','ghost')}</div>${btn(s===3?'Zakończ i przejdź do Startu':'Dalej →','wizard-next','primary')}</div></section></div>`}

function help(){const terms=D.glossary;
  return `<div class="pill-tabs mb-18">${[['glossary','Słownik'],['tutorial','Samouczek'],['report','Raport błędu']].map(t=>`<button class="pill ${ui.helpTab===t[0]?'active':''}" data-help="${t[0]}">${t[1]}</button>`).join('')}</div>${ui.helpTab==='glossary'?`<div class="grid-2">${terms.map(([name,desc])=>`<section class="panel"><div class="inline-icon cyan-text">${ico('book')} <strong style="font-size:14px">${esc(name)}</strong></div><p class="small-txt" style="margin:15px 0 0">${esc(desc)}</p></section>`).join('')}</div>`:ui.helpTab==='tutorial'?`<section class="panel">${head('Jak wygląda pierwszy trening?','Cztery kroki od uruchomienia do poprawiania czasu')}<div class="info-row"><span>01 · Ustaw telemetrię UDP w grze</span><strong>Port ${D.settings.port}, 127.0.0.1</strong></div><div class="info-row"><span>02 · Zostaw to okno i uruchom grę</span><strong>Trener startuje sam</strong></div><div class="info-row"><span>03 · Wyjedź na tor w Time Trial albo treningu</span><strong>Po pierwszym pełnym okrążeniu uwagi po zakrętach</strong></div><div class="info-row"><span>04 · Po sesji</span><strong>Podsumowanie, Analiza, Postęp</strong></div><div class="mt-20">${btn(`Uruchom samouczek 1/${TUTORIAL.length}`,'tutorial-start','primary')} ${btn('Przejdź do kreatora','open-wizard','ghost')}</div></section>`:`<section class="panel" style="max-width:760px">${head('Zgłoszenie błędu','Opisz problem. Program spakuje dziennik, bazę i ostatnie nagranie do ZIP.')}<label for="bug-desc" class="label">CO SIĘ STAŁO?</label><textarea id="bug-desc" class="textarea" placeholder="Np. Trener nie odtwarza komunikatów na Monzy...">${esc(ui.bugDesc||'')}</textarea><div class="mt-16">${btn('Zapakuj raport','report-bug-now','cyan')}</div><p class="small-txt">${esc(D.wizard.bugResult||'Plik ZIP trafi do folderu raporty-bledow; wyślij go tak jak nagrania.')}</p></section>`}<section class="panel mt-20"><h2 class="section-title">Nakładka HUD i tryb wyświetlania</h2><p class="small-txt">Aby nakładka była widoczna nad grą, ustaw w F1 25 tryb <strong>Okno bez ramki (Borderless)</strong>. Wyłączny pełny ekran zasłania nakładkę. Pozycje modułów ustawiasz w zakładce HUD F1, nie w trakcie jazdy.</p></section><section class="panel mt-20">${head('Co dalej po becie','Planowany rozwój po uruchomieniu stabilnej wersji')}<p class="small-txt">Nowe gry, rozbudowane analizy, dodatkowe funkcje inżyniera wyścigowego i chmura. W trakcie bety wszystkie obecne funkcje trenera pozostają bezpłatne.</p></section>`}

// HUD F1: edytor nakładki osadzony w programie (hud.html), układ zapisywany w ustawieniach
// wbudowane tła edytora: zrzuty z gry z podmienionymi logami i nazwami (bez znaków towarowych i danych graczy)
const HUD_BACKGROUNDS=[['tla/tlo-kokpit.jpg','Kokpit'],['tla/tlo-kamera-t.jpg','Kamera T'],['tla/tlo-maska.jpg','Maska'],['tla/tlo-tyl.jpg','Widok z tyłu']];
let hudBackgroundsAvailable=null; // sprawdzone raz: które pliki tła są w paczce
function hudBackgroundList(){ if(hudBackgroundsAvailable) return hudBackgroundsAvailable; hudBackgroundsAvailable=[]; for(const [file,label] of HUD_BACKGROUNDS){ const img=new Image(); img.onload=()=>{hudBackgroundsAvailable.push([file,label]); if(!ui.hudBackground){ui.hudBackground=hudBackgroundsAvailable[0][0]; hudInit()} render()}; img.src=file } return hudBackgroundsAvailable }
function hudView(){const bgs=hudBackgroundList();
  return `<div class="hud-v2-page"><div class="panel"><div class="spaced"><div><h2 class="section-title">HUD · osiem niezależnych modułów</h2><p class="small-txt" style="margin-bottom:0">Przeciągaj moduły (przycisk „Przesuń bloki”), zmieniaj skalę i krycie, włączaj i wyłączaj moduły. Układ zapisuje się sam. Tło: widok z gry do wyboru poniżej albo własny zrzut (2560×1440 lub 1920×1080).</p></div></div><div class="pill-tabs mt-16">${bgs.map(([file,label])=>`<button class="pill ${ui.hudBackground===file?'active':''}" data-hud-bg="${esc(file)}">${esc(label)}</button>`).join('')}<button class="pill ${ui.hudBackground&&!bgs.some(b=>b[0]===ui.hudBackground)?'active':''}" data-action="hud-photo">${ui.hudPhotoPicker?'Zamknij':'Własny zrzut…'}</button><button class="pill ${!ui.hudBackground?'active':''}" data-action="hud-photo-clear">Bez tła</button></div>${ui.hudPhotoPicker?`<div class="photo-grid">${ui.photos.length?ui.photos.map(p=>`<button data-hud-photo="${esc(p.thumb)}" title="${esc(p.name)}"><img src="${p.thumb}" alt=""></button>`).join(''):'<p class="small-txt">Brak obrazów w folderach Obrazy, Pulpit i Pobrane. Zrób zrzut ekranu w grze (np. klawisz Print Screen w Steam) i wróć tutaj.</p>'}</div>`:''}</div><iframe class="hud-v2-frame" title="Edytor nakładki HUD" id="hud-frame" src="hud.html?editor=1"></iframe><p class="small-txt">HUD działa na grze tylko w trybie okna bez ramki (Borderless). Obszar między modułami jest przezroczysty i przepuszcza kliknięcia do gry.</p></div>`}
let hudSaveTimer=null;
window.addEventListener('message',e=>{const m=e.data||{}; if(m.type==='boxbox-hud-ready'){hudInit()} else if(m.type==='boxbox-hud-layout'){clearTimeout(hudSaveTimer);hudSaveTimer=setTimeout(()=>{D.settings.hud=m.layout;D.settings.opacity=m.layout.opacity;D.settings.scale=m.layout.scale;call('setSetting',JSON.stringify({hud:m.layout}))},300)}});
function hudInit(){const f=document.getElementById('hud-frame'); if(!f||!f.contentWindow) return; f.contentWindow.postMessage({type:'boxbox-hud-init',layout:D.settings.hud||{},background:ui.hudBackground||''},'*')}

function overlayUI(){const L=D.live; const msgs=L.messages.slice(-3).reverse();
  return `<aside class="overlay" aria-label="Podgląd nakładki"><div class="overlay-bar"><strong>BOXBOX ACADEMY / NAKŁADKA (PODGLĄD)</strong><span style="color:var(--red);font-weight:800">● LIVE</span></div><div class="spaced mt-16"><div><span class="caps">${esc(L.lapLine||'')}</span><div class="overlay-corner">${esc(L.corner||'—')} <span style="font-size:14px;font-weight:600;color:#d6e6f0">${L.dist==='TERAZ'?'teraz':L.dist?'za '+esc(L.dist):''}</span></div></div><span class="tag cyan">${ui.mode==='race'?'WYŚCIG':'NAUKA'}</span></div>${L.focus?`<div class="overlay-line" style="color:var(--amber)">${esc(L.focus)}</div>`:''}${msgs.map(m=>`<div class="overlay-line"><span class="radio-time">${sec(m.t)}</span> ${esc(m.text)}</div>`).join('')}${L.goalText?`<div class="overlay-goal mt-16"><div class="spaced"><span style="font-size:12px">${esc(L.goalText)}</span><strong class="green">${L.streak}/${L.needed}</strong></div><div class="mt-10">${progress(100*L.streak/L.needed)}</div></div>`:''}<div class="spaced mt-16" style="font:11px Consolas,monospace;color:#8ba0b5"><span>${esc(L.statusLine||'')}</span><span style="color:var(--green)">${L.recording?'● NAGRYWANIE':''}</span></div></aside>`}

function renderView(){switch(ui.view){case 'start':return D.live?live():ready();case 'analysis':return analysis();case 'progress':return progressScreen();case 'skills':return skillsView();case 'lessons':return lessons();case 'driver':return driver();case 'settings':return settings();case 'wizard':return wizard();case 'summary':return summary();case 'help':return help();case 'hud':return hudView();default:return ready()}}
const app=document.getElementById('app');
const KEEP_IDS=['session-name','driver-nick','bug-desc','lesson-corner','port','fit-zoom','fit-x','fit-y'];
let lastHtml='';
// Podmiana tylko zmienionych węzłów zamiast całego innerHTML: obrazy, czcionki i animacje nie migają przy każdym odświeżeniu stanu
function morphChildren(cur,fresh){ const cn=[...cur.childNodes], fn=[...fresh.childNodes];
  for(let i=0;i<cn.length;i++){ const c=cn[i], f=fn[i]; if(c.nodeType===3&&f.nodeType===3){ if(c.nodeValue!==f.nodeValue) c.nodeValue=f.nodeValue } else if(c.nodeType===1&&f.nodeType===1) morph(c,f); else c.replaceWith(f) } }
function morph(cur,fresh){ if(cur.isEqualNode(fresh)) return;
  if(cur.tagName!==fresh.tagName||cur.childNodes.length!==fresh.childNodes.length){ cur.replaceWith(fresh); return }
  for(const a of [...cur.attributes]) if(!fresh.hasAttribute(a.name)) cur.removeAttribute(a.name);
  for(const a of [...fresh.attributes]) if(cur.getAttribute(a.name)!==a.value) cur.setAttribute(a.name,a.value);
  morphChildren(cur,fresh) }
function render(){ if(!D) return;
  const active=document.activeElement; const keep=active&&active.id&&KEEP_IDS.includes(active.id)?{id:active.id,pos:active.selectionStart}:null;
  const typed={}; for(const id of KEEP_IDS){const el=document.getElementById(id); if(el&&el.value!==el.defaultValue) typed[id]=el.value}  // to, co użytkownik wpisał, przeżywa przerysowanie
  const html=shell();
  const hudFrame=ui.view==='hud'?document.getElementById('hud-frame'):null;
  if(hudFrame){ // edytor HUD zostaje na miejscu (przeniesienie iframe = przeładowanie); odświeżamy tylko pasek boczny, nagłówek i komunikat
    const box=document.createElement('div'); box.innerHTML=html;
    for(const sel of ['.side','.header']){const cur=app.querySelector(sel), fresh=box.querySelector(sel); if(cur&&fresh&&cur.outerHTML!==fresh.outerHTML) cur.replaceWith(fresh)}
    const oldNotice=app.querySelector('.notice'), newNotice=box.querySelector('.notice'); if((oldNotice&&oldNotice.outerHTML)!==(newNotice&&newNotice.outerHTML)){ if(oldNotice) oldNotice.remove(); if(newNotice) app.querySelector('.header').after(newNotice) }
    const oldTut=app.querySelector('.tutorial'), newTut=box.querySelector('.tutorial'); if((oldTut&&oldTut.outerHTML)!==(newTut&&newTut.outerHTML)){ if(oldTut) oldTut.remove(); if(newTut) app.querySelector('.app-layout').append(newTut) }
    const oldPick=app.querySelector('.hud-v2-page .photo-grid'), newPick=box.querySelector('.hud-v2-page .photo-grid'); if((oldPick&&oldPick.outerHTML)!==(newPick&&newPick.outerHTML)){ if(oldPick) oldPick.remove(); if(newPick) app.querySelector('.hud-v2-page .panel').append(newPick) }
    const oldTabs=app.querySelector('.hud-v2-page .pill-tabs'), newTabs=box.querySelector('.hud-v2-page .pill-tabs'); if(oldTabs&&newTabs&&oldTabs.outerHTML!==newTabs.outerHTML) oldTabs.replaceWith(newTabs);
    lastHtml=''; }
  else { if(html===lastHtml) return; // nic się nie zmieniło: nie ruszamy DOM (pola tekstowe, hover, kliknięcia)
    lastHtml=html; const box=document.createElement('div'); box.innerHTML=html;
    if(app.childNodes.length!==box.childNodes.length) app.innerHTML=html; else morphChildren(app,box); }
  document.title=`BoxBox Academy | ${H[ui.view]?.[0]||'Start'}`;
  for(const id in typed){const el=document.getElementById(id); if(el) el.value=typed[id]}
  if(keep){const el=document.getElementById(keep.id); if(el){el.focus(); try{el.setSelectionRange(keep.pos,keep.pos)}catch(e){}}} }
function navigate(next){ui.view=next;ui.overlayVisible=false;ui.photoPicker=false;ui.hudPhotoPicker=false;render();window.scrollTo({top:0,behavior:'instant'});}
const call=(name,...args)=>{ if(bridge&&bridge[name]) return bridge[name](...args); };
function tutorialGo(step){ ui.tutorialStep=step; ui.tutorial=true; const view=TUTORIAL[step][0]; if(ui.view!==view) navigate(view); else render(); call('tutorialStep',String(step)); }
function tutorialEnd(){ ui.tutorial=false; if(!D.settings.tutorialDone){ D.settings.tutorialDone=true; call('setSetting', JSON.stringify({tutorialDone:true})); } render(); }

function action(a){switch(a){
 case 'start-session': call('startSession', JSON.stringify({name:ui.sessionName,record:ui.record,overlay:ui.overlay,quiet:ui.quiet,lesson:'',corner:0,mode:ui.mode})); break;
 case 'stop-session': call('stopSession'); break;
 case 'new-session': D.summary=null; navigate('start'); break;
 case 'go-start': navigate('start'); break;
 case 'go-analysis': navigate('analysis'); break;
 case 'skills-start': navigate('start'); break;
 case 'skills-lesson': { const rec=skillsRecommendation(); if(rec){ ui.lesson=SKILL_LESSON[rec.key]||'clean_lap'; ui.lessonCorner=rec.corner||''; } navigate('lessons'); break; }
 case 'skills-back': ui.skillsFocus=null; navigate('skills'); break;
 case 'open-lesson': navigate('lessons'); break;
 case 'open-hud': navigate('hud'); break;
 case 'start-lesson': { const corner=parseInt((document.getElementById('lesson-corner')||{}).value||'0')||0; ui.lessonCorner=corner||''; call('startSession', JSON.stringify({name:'Lekcja',record:ui.record,overlay:ui.overlay,quiet:false,lesson:ui.lesson,corner})); navigate('start'); break; }
 case 'toggle-overlay': ui.overlayVisible=!ui.overlayVisible; render(); break;
 case 'preview-overlay': call('previewOverlay'); showNotice('info','Nakładka pokazana na 5 s'); break;
 case 'notice-close': { const n=currentNotice(); if(n&&n.derived==='busy') ui.busyDismissed=true; ui.notice=null; render(); break; }
 case 'wizard-next': if(ui.wizardStep<3){ui.wizardStep++;render()} else { const nick=(document.getElementById('driver-nick')||{}).value||''; call('finishWizard', nick); const first=!D.settings.tutorialDone; D.settings.wizardDone=true; navigate('start'); if(first) tutorialGo(0); } break;
 case 'wizard-back': if(ui.wizardStep>0){ui.wizardStep--;render()} else navigate('start'); break;
 case 'open-wizard': ui.wizardStep=0; navigate('wizard'); break;
 case 'tutorial': ui.helpTab='tutorial'; navigate('help'); break;
 case 'tutorial-start': tutorialGo(0); break;
 case 'tutorial-next': if(ui.tutorialStep>=TUTORIAL.length-1) tutorialEnd(); else tutorialGo(ui.tutorialStep+1); break;
 case 'tutorial-close': tutorialEnd(); break;
 case 'glossary': ui.helpTab='glossary'; navigate('help'); break;
 case 'report-bug': ui.helpTab='report'; navigate('help'); break;
 case 'report-bug-now': { ui.bugDesc=(document.getElementById('bug-desc')||{}).value||''; call('bugReport', ui.bugDesc); break; }
 case 'check-telemetry': call('checkTelemetry'); break;
 case 'audio-sample': call('playSample'); showNotice('info','Odtwarzam powitanie'); break;
 case 'hear-yes': D.wizard.hearResult='Dobrze. Głośność zmienisz w Ustawieniach → Dźwięk.'; render(); break;
 case 'hear-no': D.wizard.hearResult='Sprawdź w Windows: Ustawienia → Dźwięk → urządzenie wyjściowe (słuchawki/głośniki) i głośność, potem Odtwórz ponownie.'; render(); break;
 case 'license-help': showNotice('info','Poziom licencji to najwyższy osiągnięty krok asyst na dowolnym torze.'); break;
 case 'export-csv': call('exportCsv'); break;
 case 'print-pdf': call('printPdf'); break;
 case 'session-report': call('sessionReport'); showNotice('info','Zapisuję raport PDF…'); break;
 case 'export-license': exportLicense(); break;
 case 'save-nick': { const nick=(document.getElementById('driver-nick')||{}).value||''; call('setSetting', JSON.stringify({nick})); showNotice('success','Zapisano nick'); break; }
 case 'pick-photo': ui.photoPicker=!ui.photoPicker; if(ui.photoPicker) call('listPhotos'); render(); break;
 case 'photo-fit': ui.photoFit=!ui.photoFit; ui.fitDraft=ui.photoFit?{...D.driver.photoFit}:null; render(); break;
 case 'photo-fit-save': if(ui.fitDraft){ D.driver.photoFit={...ui.fitDraft}; call('setSetting',JSON.stringify({photoFit:ui.fitDraft})); } ui.photoFit=false; ui.fitDraft=null; render(); break;
 case 'photo-fit-reset': ui.fitDraft={x:50,y:50,zoom:100}; applyFitDraft(); break;
 case 'hud-photo': ui.hudPhotoPicker=!ui.hudPhotoPicker; if(ui.hudPhotoPicker) call('listPhotos'); render(); break;
 case 'hud-photo-clear': ui.hudBackground=''; hudInit(); render(); break;
 case 'open-data': call('openDataDir'); break;
 case 'open-recordings': call('openRecordingsDir'); break;
 default: break; } }

function exportLicense(){const d=D.driver;let c=document.createElement('canvas');c.width=980;c.height=565;const g=c.getContext('2d');const grd=g.createLinearGradient(0,0,980,565);grd.addColorStop(0,'#253044');grd.addColorStop(1,'#0c131f');g.fillStyle=grd;g.fillRect(0,0,980,565);g.fillStyle='#ff3c42';g.fillRect(0,136,980,7);g.fillStyle='#f1f5fa';g.font='bold 40px Inter, Segoe UI, Arial';g.fillText('BOXBOX ACADEMY',54,77);g.fillStyle='#9aacc1';g.font='19px Inter, Segoe UI, Arial';g.fillText('LICENCJA KIEROWCY',56,113);g.fillStyle='#19e6e6';g.font='bold 58px Barlow Condensed, Inter, Arial';g.fillText('L'+d.level,835,105);g.fillStyle='#f1f5fa';g.font='bold 62px Inter, Segoe UI, Arial';g.fillText((d.nick||'KIEROWCA').toUpperCase(),66,248);g.fillStyle='#19e6e6';g.font='25px Inter, Segoe UI, Arial';g.fillText(d.id,66,286);g.fillStyle='#b2c2d2';g.font='27px Inter, Segoe UI, Arial';g.fillText('Krok asyst  ·  '+d.stepText,65,358);g.fillText('Tory  ·  '+d.tracksText,65,402);g.fillText('Okrążenia  ·  '+d.laps,65,446);g.fillText('Seria  ·  '+d.streakText,65,490);g.fillStyle='#314255';g.fillRect(580,457,334,15);g.fillStyle='#35d07f';g.fillRect(580,457,Math.round(334*d.progressPct/100),15);g.fillStyle='#718499';g.font='18px Inter, Segoe UI, Arial';g.fillText('BOXBOX ACADEMY · od '+d.since,580,510);call('saveLicensePng', c.toDataURL('image/png'));}

app.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){navigate(n.dataset.nav);return}const a=e.target.closest('[data-action]');if(a){action(a.dataset.action);return}const t=e.target.closest('[data-toggle]');if(t){const x=t.dataset.toggle; if(['record','overlay','quiet'].includes(x)){ui[x]=!ui[x]} else {D.settings[x]=!D.settings[x]; call('setSetting', JSON.stringify({[x]:D.settings[x]}))} render();return}const md=e.target.closest('[data-mode]');if(md){ui.mode=md.dataset.mode;render();return}const cor=e.target.closest('[data-corner]');if(cor){ui.corner=cor.dataset.corner;render();return}const sk=e.target.closest('[data-skills-track]');if(sk){ui.skillsTrack=sk.dataset.skillsTrack;render();return}const so=e.target.closest('[data-skill-open]');if(so){ui.skillsFocus=so.dataset.skillOpen; if(so.dataset.skillCorner) ui.corner=so.dataset.skillCorner; navigate('analysis');return}const tr=e.target.closest('[data-track]');if(tr){call('selectTrack',tr.dataset.track);return}const st=e.target.closest('[data-settings]');if(st){ui.settingsTab=st.dataset.settings;render();return}const help=e.target.closest('[data-help]');if(help){ui.helpTab=help.dataset.help;render();return}const les=e.target.closest('[data-lesson]');if(les){ui.lesson=les.dataset.lesson;render();return}const sort=e.target.closest('[data-sort]');if(sort){const idx=Number(sort.dataset.sort);ui.sortDir=ui.sortBy===idx?-ui.sortDir:1;ui.sortBy=idx;render();return}const hp=e.target.closest('[data-hud-photo]');if(hp){ui.hudBackground=hp.dataset.hudPhoto;ui.hudPhotoPicker=false;render();hudInit();return}const hb=e.target.closest('[data-hud-bg]');if(hb){ui.hudBackground=hb.dataset.hudBg;ui.hudPhotoPicker=false;render();hudInit();return}const ph=e.target.closest('[data-photo]');if(ph){call('setPhoto',ph.dataset.photo);ui.photoPicker=false;return}});
app.addEventListener('input',e=>{const id=e.target.id; if(!ui.fitDraft||!['fit-zoom','fit-x','fit-y'].includes(id)) return; ui.fitDraft[id==='fit-zoom'?'zoom':id==='fit-x'?'x':'y']=parseInt(e.target.value)||0; applyFitDraft()});
let fitDrag=null;
app.addEventListener('pointerdown',e=>{const pv=e.target.closest('#photo-fit-preview'); if(!pv||!ui.fitDraft) return; fitDrag={x:e.clientX,y:e.clientY,fx:ui.fitDraft.x,fy:ui.fitDraft.y,w:pv.clientWidth,h:pv.clientHeight}; pv.setPointerCapture(e.pointerId); e.preventDefault()});
app.addEventListener('pointermove',e=>{if(!fitDrag||!ui.fitDraft) return; const k=100/Math.max(1,(ui.fitDraft.zoom/100-1)*fitDrag.w||fitDrag.w); ui.fitDraft.x=Math.max(0,Math.min(100,Math.round(fitDrag.fx-(e.clientX-fitDrag.x)*k))); ui.fitDraft.y=Math.max(0,Math.min(100,Math.round(fitDrag.fy-(e.clientY-fitDrag.y)*k))); applyFitDraft()});
app.addEventListener('pointerup',()=>{fitDrag=null}); app.addEventListener('pointercancel',()=>{fitDrag=null});
app.addEventListener('change',e=>{const id=e.target.id; if(id==='session-name'){ui.sessionName=e.target.value} if(id==='an-session'){call('selectAnalysis',JSON.stringify({session:e.target.value}))} if(id==='an-lap'){call('selectAnalysis',JSON.stringify({lap:e.target.value}))} if(id==='an-comp'){call('selectAnalysis',JSON.stringify({comp:e.target.value}))} if(id==='volume'){call('setSetting',JSON.stringify({volume:parseInt(e.target.value)}))} if(id==='scale'){call('setSetting',JSON.stringify({scale:parseInt(e.target.value)}))} if(id==='opacity'){call('setSetting',JSON.stringify({opacity:parseInt(e.target.value)}))} if(id==='port'){call('setSetting',JSON.stringify({port:parseInt(e.target.value)||20777}))} if(id==='lesson-corner'){ui.lessonCorner=e.target.value}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.license[data-nav]')){e.preventDefault();navigate('driver')}if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-corner]')){e.preventDefault();ui.corner=e.target.closest('[data-corner]').dataset.corner;render()}});
document.addEventListener('dragover',e=>e.preventDefault()); document.addEventListener('drop',e=>e.preventDefault()); // upuszczony plik obsługuje okno Qt (ścieżka pliku nie jest dostępna w przeglądarce)

// --- połączenie z Pythonem ---
function applyData(json, partial){ const d=typeof json==='string'?JSON.parse(json):json; if(partial&&D){ Object.assign(D,d) } else { D=d } ; if(D && d.view){ ui.view=d.view } render(); }
// --- Umiejętności (makieta v4): dane z D.skills (silnik coach/skills.py), bez liczenia w oknie ---
const SKILL_DEFS=[
 {id:'braking',name:'Hamowanie',lines:['Hamowanie']},
 {id:'brake_control',name:'Praca hamulcem',lines:['Praca','hamulcem']},
 {id:'throttle',name:'Gaz na wyjściu',lines:['Gaz na','wyjściu']},
 {id:'consistency',name:'Powtarzalność',lines:['Powtarzalność']},
 {id:'pace',name:'Tempo',lines:['Tempo']},
 {id:'independence',name:'Samodzielność',lines:['Samodzielność']}];
const SKILL_LESSON={braking:'braking_one_corner',brake_control:'trail_braking',throttle:'throttle_exit',consistency:'clean_lap',pace:'braking_one_corner',independence:'clean_lap'};
const SKILL_BASIS={braking:'twoje najlepsze',brake_control:'twoje najlepsze',throttle:'twoje najlepsze',consistency:'stałe progi',pace:'twoje najlepsze',independence:'ścieżka asyst'};
function skillsProfile(){const S=D.skills; if(!S) return null; if(ui.skillsTrack==='all'||!S.tracks.length) return S.all; return S.tracks.find(t=>String(t.trackId)===String(ui.skillsTrack))||S.all;}
function skillsScores(p){return SKILL_DEFS.map(d=>{const s=p&&p.skills.find(x=>x.key===d.id); return s&&s.score!==null&&s.score!==undefined?s.score:null})}
function skillsPolygon(scores,cx,cy,r){return scores.map((v,i)=>{const a=Math.PI*(i/3-.5),d=r*(Math.max(0,Math.min(100,v??0))/100);return [(cx+Math.cos(a)*d).toFixed(1),(cy+Math.sin(a)*d).toFixed(1)].join(',')}).join(' ')}
function skillRadarSVG(scores,previous,tiny=false){
 const cx=tiny?60:260,cy=tiny?60:260,r=tiny?46:146,W=tiny?120:520,H=tiny?120:520; const rad=i=>Math.PI*(i/3-.5);
 const grids=[20,40,60,80,100].map(v=>`<polygon class="skill-radar-grid" points="${skillsPolygon(Array(6).fill(v),cx,cy,r)}"/>`).join('');
 const axes=SKILL_DEFS.map((_,i)=>`<line class="skill-radar-axis" x1="${cx}" y1="${cy}" x2="${(cx+Math.cos(rad(i))*r).toFixed(1)}" y2="${(cy+Math.sin(rad(i))*r).toFixed(1)}"/>`).join('');
 const nums=tiny?'':`<text x="${cx+5}" y="${cy-r*.8-6}" fill="#6f8a9d" font-size="11">80</text><text x="${cx+5}" y="${cy-r*.4-5}" fill="#6f8a9d" font-size="11">40</text>`;
 const positions=[[260,48,'middle'],[422,146,'middle'],[431,367,'middle'],[260,471,'middle'],[83,367,'middle'],[87,146,'middle']];
 const labels=tiny?'':SKILL_DEFS.map((d,i)=>{const [x,y,anchor]=positions[i];const shown=scores[i];return `<text x="${x}" y="${y}" text-anchor="${anchor}" class="skill-radar-label">${d.lines.map((part,j)=>`<tspan x="${x}" dy="${j===0?0:16}">${part}</tspan>`).join('')}<tspan x="${x}" dy="21" class="skill-radar-value">${shown===null?'—':shown}</tspan></text>`}).join('');
 const current=scores.every(v=>v!==null)?`<polygon class="skill-radar-current" points="${skillsPolygon(scores,cx,cy,r)}"/>`:'';
 const prev=previous&&previous.every(v=>v!==null)?`<polygon class="skill-radar-prev" points="${skillsPolygon(previous,cx,cy,r)}"/>`:'';
 const dots=scores.map((v,i)=>{const a=rad(i),dist=r*((v===null?0:v)/100);return `<circle cx="${(cx+Math.cos(a)*dist).toFixed(1)}" cy="${(cy+Math.sin(a)*dist).toFixed(1)}" r="${tiny?2:4}" fill="${v===null?'#778596':'#19e6e6'}" stroke="#192637" stroke-width="${tiny?0:2}"/>`}).join('');
 return `<svg class="skill-radar-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Radar sześciu umiejętności: ${SKILL_DEFS.map((d,i)=>d.name+' '+(scores[i]??'za mało danych')).join(', ')}"><defs><radialGradient id="radarGlow${tiny?'T':''}"><stop offset="0" stop-color="#19e6e6" stop-opacity=".07"/><stop offset="1" stop-color="#19e6e6" stop-opacity="0"/></radialGradient></defs><circle cx="${cx}" cy="${cy}" r="${r*1.05}" fill="url(#radarGlow${tiny?'T':''})"/>${grids}${axes}${nums}${prev}${current}${dots}${labels}</svg>`;}
function skillCard(d,s){const v=s&&s.score!==null&&s.score!==undefined?s.score:null,t=s&&s.trend!==null&&s.trend!==undefined?s.trend:null; const basis=SKILL_BASIS[d.id]||'';
 return `<button type="button" class="skill-card" data-skill-open="${d.id}" ${s&&s.cornerName?`data-skill-corner="${esc(s.cornerName)}"`:''} aria-label="Otwórz analizę: ${d.name}, wynik ${v===null?'za mało danych':v+' na 100'}"><div class="skill-card-top"><span class="skill-card-name">${d.name}</span><span class="skill-card-more">ANALIZA ↗</span></div><div class="skill-card-number"><strong class="skill-number">${v===null?'—':v}</strong><span class="skill-unit">${v===null?'za mało danych':'/ 100'}</span>${t===null?'':`<span class="skill-trend ${t>=0?'pos':'neg'}">${t>=0?'▲ +':'▼ −'}${Math.abs(t)}</span>`}</div><div class="skill-gauge"><span style="width:${Math.max(0,v??0)}%"></span></div><p class="skill-tip">${s&&s.hint?esc(s.hint.charAt(0).toUpperCase()+s.hint.slice(1))+'.':(v===null?'Za mało okrążeń, żeby ocenić.':'Tak trzymaj.')}</p><span class="skill-basis">Względem: ${basis}</span></button>`}
function skillsRecommendation(){const p=skillsProfile(); if(!p) return null; const list=SKILL_DEFS.map(d=>{const s=p.skills.find(x=>x.key===d.id)||{}; return {key:d.id,name:d.name,score:s.score,trend:s.trend,hint:s.hint,corner:s.cornerName||''}}).filter(x=>x.score!==null&&x.score!==undefined).sort((a,b)=>a.score-b.score||((a.trend??0)-(b.trend??0))); return list[0]||null}
function skillsView(){const S=D.skills, p=skillsProfile();
 const tabs=`<div class="skills-toolbar"><div class="pill-tabs" role="group" aria-label="Wybierz tor"><button type="button" class="pill ${ui.skillsTrack==='all'?'active':''}" data-skills-track="all">Wszystkie tory</button>${(S?S.tracks:[]).map(t=>`<button type="button" class="pill ${String(ui.skillsTrack)===String(t.trackId)?'active':''}" data-skills-track="${t.trackId}">${esc(t.track)}</button>`).join('')}</div><span class="tag cyan">SZEŚĆ WYMIARÓW · BEZ OCENY ŁĄCZNEJ</span></div>`;
 if(!p) return `${tabs}<section class="panel skill-empty-shell"><div class="empty-state"><div class="skill-empty-illustration" aria-hidden="true">${skillEmptySvg()}</div><h3>Twój profil właśnie się tworzy</h3><p>Przejedź pierwszą sesję z trenerem, a po ${S?S.minLaps:5} ważnych okrążeniach zobaczysz swój profil.</p>${btn(`${ico('play')} Jedź`,'skills-start','primary')}</div></section><p class="skill-educational-note">Profil powstaje z minimum ${S?S.minLaps:5} ważnych okrążeń. Samodzielność jest śledzona od pierwszego przejazdu.</p>`;
 const n=p.lapsUsed, min=S.minLaps, scores=skillsScores(p); const trends=SKILL_DEFS.map(d=>{const s=p.skills.find(x=>x.key===d.id); return s&&s.trend!==null&&s.trend!==undefined?s.trend:null});
 const previous=trends.every(t=>t!==null)&&scores.every(v=>v!==null)?scores.map((v,i)=>Math.max(0,Math.min(100,v-trends[i]))):null;
 const where=ui.skillsTrack==='all'?'wszystkie tory':p.track;
 const context=`<div class="skills-meta"><strong>${n>=S.window?`${S.window} ostatnich ważnych okrążeń`:`${n} ważnych okrążeń`} · ${esc(where)}</strong><span>Referencja: ${esc(p.ref||'twoje najlepsze okrążenie')}</span></div>`;
 if(n<min){const left=Math.max(1,min-n); return `${tabs}${context}<section class="panel skill-empty-shell"><div class="empty-state"><div class="skill-empty-illustration" aria-hidden="true">${skillEmptySvg()}</div><h3>Twój profil właśnie się tworzy</h3><p>Przejedź jeszcze <strong>${left} ${left===1?'okrążenie':left<5?'okrążenia':'okrążeń'}</strong> na ${ui.skillsTrack==='all'?'wybranych torach':'torze '+esc(p.track)}, a zobaczysz swój profil.</p>${btn(`${ico('play')} Jedź`,'skills-start','primary')}</div></section><p class="skill-educational-note">Profil powstaje z minimum ${min} ważnych okrążeń. Samodzielność jest śledzona od pierwszego przejazdu.</p>`;}
 const focus=skillsRecommendation(); const lessonTitle=focus&&D.lessons?(D.lessons.cards.find(c=>c.id===SKILL_LESSON[focus.key])||{}).title:'';
 return `${tabs}${context}<div class="skill-layout"><section class="panel skill-radar-panel"><div class="panel-header"><div><div class="caps">PROFIL KIEROWCY</div><h2 class="section-title" style="font-size:21px;margin-top:10px">Twoja mapa treningu</h2><p class="section-sub">Wyniki 0–100 · porównanie do własnej referencji</p></div><span class="tag cyan">${esc(where)}</span></div>${skillRadarSVG(scores,previous)}<div class="skill-legend"><span><i class="skill-line"></i> Obecne ${Math.min(n,S.window)} okrążeń</span>${previous?`<span><i class="skill-line previous"></i> Poprzednie ${S.window}</span>`:''}</div><p class="skill-help">Wysoki wynik oznacza, że powtarzasz swoje najlepsze zachowania, a nie że jeździsz jak zawodowiec. To mapa pracy, nie ranking.</p></section><section class="skill-cards" aria-label="Sześć wymiarów umiejętności">${SKILL_DEFS.map(d=>skillCard(d,p.skills.find(x=>x.key===d.id))).join('')}</section></div>${focus?`<section class="panel skill-goal"><div><div class="caps">ZADANIE NA NASTĘPNĄ SESJĘ</div><p class="skill-goal-text">${esc(focus.hint?focus.hint.charAt(0).toUpperCase()+focus.hint.slice(1)+'.':'Powtórz swoje najlepsze okrążenie.')}</p><span class="skill-goal-detail">Największa przestrzeń do poprawy: ${focus.name} · ${focus.score}/100.${lessonTitle?` Lekcja: ${esc(lessonTitle)}.`:''}</span></div>${btn(`${ico('play')} Zacznij lekcję`,'skills-lesson','primary')}</section>`:''}`;}
function skillEmptySvg(){return `<svg viewBox="0 0 120 120"><g fill="none" stroke="#19e6e6" stroke-width="2"><path d="M60 11 104 42 88 96H32L16 42Z"/><path d="M60 11v45l44-14M60 56 16 42m44 14-28 40m28-40 28 40" opacity=".4"/><path d="M60 43 76 55 72 74H48L44 55Z" stroke-dasharray="4 5"/></g><circle cx="60" cy="57" r="6" fill="#19e6e6"/></svg>`}
window.boxbox = { applyData, toast, showNotice, navigate, ui, TUTORIAL };
function connect(){ if(typeof QWebChannel==='undefined'||!window.qt||!qt.webChannelTransport){ return false }
  new QWebChannel(qt.webChannelTransport, ch => { bridge = ch.objects.bridge; window.boxbox.bridge = bridge; bridge.dataChanged.connect(j=>applyData(j,false)); bridge.liveChanged.connect(j=>applyData(j,true)); bridge.toast.connect(m=>toast(m)); bridge.notice.connect((t,m)=>showNotice(t,m)); bridge.navigateTo.connect(v=>navigate(v)); bridge.photos.connect(j=>{ui.photos=JSON.parse(j);render()}); bridge.getData(j=>{ applyData(j,false); if(!D.settings.wizardDone){ ui.wizardStep=0; navigate('wizard') } ui.sessionName=D.defaultSessionName||'sesja'; ui.record=!!D.settings.record; ui.overlay=!!D.settings.overlayDefault; ui.quiet=!!D.settings.quietDefault; render(); }); });
  return true; }
if(!connect()){ // podgląd w przeglądarce bez Pythona: dane przykładowe z pliku demo.js (jeśli jest)
  const s=document.createElement('script'); s.src='demo.js'; s.onload=()=>{ if(window.DEMO) applyData(window.DEMO,false) }; document.body.appendChild(s); }
})();
